window.BANK=[{"id": "L13-2001", "codes": ["L13102"], "diff": "易", "level": "知識", "stem": "CIE 定義的明視覺光譜光視效率函數 V(λ)，其最大值落在哪個波長附近？", "opts": ["507 nm", "580 nm", "555 nm", "450 nm"], "explain": "明視覺由錐狀細胞主導，V(λ) 峰值在 555 nm（黃綠）。暗視覺由桿狀細胞主導，V′(λ) 峰值在 507 nm。", "trap": "507 nm 是暗視覺峰值，專門用來測學生是否混淆明視覺與暗視覺。", "src": "科目三指引 1.1（第 2-3 頁）", "fam": "L13-2001", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115考前模擬v1", "diag": false, "ans": "C"}, {"id": "L13-2002", "codes": ["L13104"], "diff": "易", "level": "應用", "stem": "以濃度計量測某印刷色塊，得到反射率 R = 0.01。其反射濃度 D 為多少？", "opts": ["0.01", "2.0", "1.0", "100"], "explain": "反射濃度 D = log₁₀(1/R) = log₁₀(100) = 2.0。純白（R≈1）的濃度約為 0。", "trap": "0.01 與 100 是把 R 或 1/R 直接當答案，沒有取對數。", "src": "科目三指引 2.1（第 2-32 頁）", "fam": "density", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115考前模擬v1", "diag": false, "ans": "B"}, {"id": "L13-2003", "codes": ["L13101"], "diff": "易", "level": "知識", "stem": "CIE 標準照明體 D65 指的是下列何者？", "opts": ["相關色溫 2856 K 的鎢絲燈", "各波長能量相等的等能白光", "三波長型螢光燈", "相關色溫約 6500 K 的代表性日光"], "explain": "D 系列是 CIE 以公式定義的日光，D65 對應約 6500 K；A 為鎢絲燈 2856 K，E 為等能白光，F 系列為螢光燈。", "trap": "三個誘答分別對應 A、E、F 照明體，檢查學生能否區分照明體代號。", "src": "科目三指引 1.2（第 2-8～2-9 頁）", "fam": "L13-2003", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115考前模擬v1", "diag": false, "ans": "D"}, {"id": "L13-2004", "codes": ["L13203"], "diff": "易", "level": "理解", "stem": "一般 LCD 液晶顯示器呈現白色畫面的原理，下列敘述何者正確？", "opts": ["背光經紅、綠、藍彩色濾光片形成子畫素，以並置加法混色在視覺上合成白色", "紅、綠、藍色光依時間快速輪流出現，以時序混色合成白色", "每個畫素的有機發光層直接發出白光", "紅、綠、藍彩色濾光片重疊，以減法混色合成白色"], "explain": "LCD 不自發光，背光通過液晶與 RGB 彩色濾光片，相鄰的極小子畫素超出眼睛空間解析力，形成並置加法混色。", "trap": "時序混色是單晶片 DLP 的機制；自發光是 OLED；濾光片重疊是減法混色的典型迷思。", "src": "科目一指引 2.7（第 2-38、2-40 頁）；陳鴻興簡報", "fam": "L13-2004", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "A"}, {"id": "L13-2005", "codes": ["L13205"], "diff": "易", "level": "理解", "stem": "四色印刷在 CMY 之外加入黑版（K），下列何者「不是」加入黑版的目的？", "opts": ["提高暗部濃度與明暗對比", "讓灰色平衡更穩定", "擴大印刷在青綠色區域的色域", "避免黑色細線因三色套印不準而出現彩色邊緣"], "explain": "黑版主要用於暗部濃度、灰平衡與細線品質；它是無彩色，無法擴大青綠等彩色區域的色域。", "trap": "青綠色域常和「印刷色域在青綠區超出 sRGB」的知識混在一起，是刻意的錯置。", "src": "科目三指引 2.3（第 2-46 頁）", "fam": "L13-2005", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "C"}, {"id": "L13-2006", "codes": ["L13303"], "diff": "易", "level": "知識", "stem": "ICC 色彩管理架構中，「描述檔連接空間」（PCS）採用的是？", "opts": ["以 D50 為參考白的 CIELAB（或 CIEXYZ）", "以 D65 為參考白的 CIELAB", "sRGB", "YCbCr"], "explain": "ICC 規定 PCS 是裝置無關空間，參考白為 D50，可用 CIELAB 或 CIEXYZ 表示。", "trap": "D65 是 sRGB 與顯示器常見白點，最容易被誤認為 PCS 的白點。", "src": "科目三指引 2.3（第 2-44 頁）；徐明景簡報", "fam": "L13-2006", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "A"}, {"id": "L13-2007", "codes": ["L13302"], "diff": "易", "level": "知識", "stem": "色彩管理的「3C」，正確的執行順序為何？", "opts": ["特性描述 → 校準 → 轉換", "轉換 → 校準 → 特性描述", "校準 → 轉換 → 特性描述", "校準（Calibration）→ 特性描述（Characterization）→ 轉換（Conversion）"], "explain": "先讓裝置回到穩定標準狀態（校準），再量測建立訊號與色度的關係（特性描述，產出描述檔），最後才能做轉換。", "trap": "把特性描述放在校準前，代表描述的是不穩定的狀態，描述檔很快就失效。", "src": "科目一指引 2.6；徐明景簡報", "fam": "L13-2007", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "D"}, {"id": "L13-2008", "codes": ["L13206"], "diff": "易", "level": "理解", "stem": "染廠預測新配方的顏色時，常把反射率換算成 K/S 值來計算，而不直接把各染料的反射率相加。原因是？", "opts": ["反射率無法用儀器量測", "K/S 與染料濃度大致成比例，可依配方相加；反射率則不能直接相加", "K/S 值就是 CIELAB 的明度", "K/S 只用在印刷，不用在紡織"], "explain": "Kubelka–Munk 理論以吸收係數 K 與散射係數 S 描述色料，K/S 與色料濃度近似呈線性、可依配方加總，再換回反射率，因此廣泛用於紡織配色與修色。", "trap": "", "src": "科目三指引 2.3（第 2-48 頁）", "fam": "L13-2008", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "B"}, {"id": "L13-2009", "codes": ["L13101", "L13103"], "diff": "中", "level": "理解", "stem": "兩塊布樣在 D65 對色燈箱下看起來完全相同，拿到店內鎢絲燈（A 光源）下卻明顯不同。下列解釋與處置何者最恰當？", "opts": ["布料色牢度不足，在鎢絲燈的熱度下褪色", "觀察者改用 10° 視角就能讓兩塊布在任何光源下都等色", "兩者光譜反射率不同，屬於同色異譜（metamerism）；對色時應在 D65、A、F 等多種光源下檢查", "兩塊布的光澤不同，只要改用 SPEX 量測即可解決"], "explain": "不同光譜反射率的兩個樣本，可能在某一光源與觀察者條件下等色，換光源就不等色，這就是條件等色。品管上要用多光源對色或比對光譜曲線。", "trap": "色牢度、觀察者視角與光澤都是真實概念，但都不能解釋「換光源才不等色」。", "src": "科目三指引 1.3（第 2-12 頁）", "fam": "L13-2009", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115考前模擬v1", "diag": false, "ans": "C"}, {"id": "L13-2010", "codes": ["L13103", "L13102"], "diff": "中", "level": "應用", "stem": "某色光以分光輻射儀量得三刺激值 X = 30、Y = 40、Z = 30（以 cd/m² 為單位換算）。下列敘述何者正確？", "opts": ["色度座標 (x, y) = (0.30, 0.40)，亮度為 100 cd/m²", "色度座標 (x, y) = (0.30, 0.40)，亮度為 40 cd/m²", "色度座標 (x, y) = (0.43, 0.57)，亮度為 40 cd/m²", "色度座標 (x, y) = (30, 40)，亮度無法得知"], "explain": "x = X/(X+Y+Z) = 30/100 = 0.30，y = 40/100 = 0.40。y̅ 色匹配函數等同 V(λ)，所以 Y 代表亮度，為 40 cd/m²。", "trap": "把 X+Y+Z 當亮度，或只用 X、Y 兩項計算比值（0.43、0.57），都是常見錯誤。", "src": "科目三指引 1.3（第 2-15～2-17 頁）", "fam": "xy", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115考前模擬v1", "diag": false, "ans": "B"}, {"id": "L13-2011", "codes": ["L13105", "L13103"], "diff": "中", "level": "應用", "stem": "標準色 CIELAB = (50, 10, 10)，樣品 = (52, 13, 14)。下列何者正確？", "opts": ["ΔE*ab ≈ 5.4；樣品比標準偏亮、偏紅、偏黃", "ΔE*ab ≈ 5.4；樣品比標準偏暗、偏綠、偏藍", "ΔE*ab = 9；樣品比標準偏亮、偏紅、偏黃", "ΔE*ab = 29；樣品比標準偏亮、偏綠、偏黃"], "explain": "ΔL* = +2（偏亮）、Δa* = +3（偏紅）、Δb* = +4（偏黃）；ΔE*ab = √(4+9+16) = √29 ≈ 5.4。", "trap": "9 是把三個差值直接相加；29 是忘了開根號；方向題常把 +a*、+b* 的意義顛倒。", "src": "科目三指引 1.5（第 2-25 頁）；科目二指引 1.2", "fam": "deltaE", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115考前模擬v1", "diag": false, "ans": "A"}, {"id": "L13-2012", "codes": ["L13104", "L13207"], "diff": "中", "level": "理解", "stem": "以 d/8° 幾何條件量測一塊高光澤汽車烤漆，分別用 SPIN 與 SPEX 模式。下列敘述何者正確？", "opts": ["霧面樣本的 SPIN 與 SPEX 差異最大", "SPEX 是指量測時包含鏡面反射成分", "45°/0° 幾何條件會把鏡面反射一併量入", "高光澤樣本兩模式的差異明顯；SPEX 排除鏡面反射，量得的 L* 通常較低，較接近避開反光時人眼看到的顏色"], "explain": "SPIN = specular included，SPEX = specular excluded。光澤越高，鏡面反射成分越多，兩模式差異越大；排除反光後反射量較少，L* 較低。45°/0° 本身就不含鏡面反射。", "trap": "考 SPIN／SPEX 的縮寫意義，以及材質光澤與量測幾何的關係。", "src": "科目三指引 2.1（第 2-35～2-36 頁）", "fam": "spex", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115考前模擬v1", "diag": false, "ans": "D"}, {"id": "L13-2013", "codes": ["L13204", "L13101"], "diff": "中", "level": "應用", "stem": "在鎢絲燈下拍攝的影像，整體平均 RGB = (150, 100, 60)。若用「灰色世界法」並以 G 平均值為基準做白平衡，下列何者正確？", "opts": ["R 增益約 1.5、B 增益約 0.6，可修正低色溫光源造成的偏藍", "三通道增益都是 1，因為灰色世界法只調整亮度", "R 增益約 0.67、B 增益約 1.67，可修正低色溫光源造成的偏黃紅", "以影像最亮點當作白色來計算增益"], "explain": "灰色世界法假設影像平均應為灰：R′ = R × (Ḡ/R̄) = R × 100/150 ≈ 0.67R；B′ = B × 100/60 ≈ 1.67B。低色溫光源偏黃紅，所以要壓 R、拉 B。", "trap": "以最亮點當白是「最大 RGB 值法」；倒數方向弄反會得到 1.5 與 0.6。", "src": "科目三指引 2.3（第 2-44～2-45 頁）", "fam": "wb", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "C"}, {"id": "L13-2014", "codes": ["L13305", "L13205"], "diff": "中", "level": "應用", "stem": "一批以 Adobe RGB 拍攝、含大量鮮豔自然風景的照片要轉成銅版紙 CMYK 印刷，許多顏色超出印刷色域。一般建議選用哪一種演色意圖？", "opts": ["飽和度式（saturation）：優先保持鮮豔度，適合照片", "絕對色度式（absolute colorimetric）：色域外顏色不會被裁切", "演色意圖只影響色域內的顏色，選哪一種都一樣", "感應式（perceptual）：整體壓縮色域，保持色彩間的相對關係與階調"], "explain": "自然影像轉到較小的色域時，感應式會整體調整，避免色域外的顏色被裁切成一片、失去層次。飽和度式適合商業圖表；色度式會裁切色域外顏色。", "trap": "「照片很鮮豔，所以用飽和度式」是常見直覺錯誤。實務上也常用相對色度式搭配黑點補償，可在解析中延伸討論。", "src": "科目一指引 2.6（第 2-36 頁）；科目二指引 2.4", "fam": "intent", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "D"}, {"id": "L13-2015", "codes": ["L13203", "L13302"], "diff": "中", "level": "應用", "stem": "設計師要為一般 sRGB 網頁與影像工作「校準」螢幕。下列哪組目標設定最合適？", "opts": ["亮度約 120 cd/m²、白點 6500 K（D65）、gamma 2.2", "亮度調到最大、白點 9300 K、gamma 1.0", "亮度約 500 cd/m²、白點 5000 K、gamma 1.8", "不需設定，安裝 ICC 描述檔就等於完成校準"], "explain": "sRGB 規格採 D65 白點與約 2.2 的 gamma，一般編修環境亮度約 80–120 cd/m²。校準是把裝置調回標準狀態，描述檔是之後特性描述的產物。", "trap": "最後一個選項混淆了「校準」與「特性描述」，這是 3C 最常見的觀念錯誤。", "src": "徐明景簡報（3C 之校準）；科目三指引 2.3", "fam": "L13-2015", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "A"}, {"id": "L13-2016", "codes": ["L13201", "L13203", "L13205"], "diff": "中", "level": "理解", "stem": "比較 sRGB 顯示器與一般平版印刷（塗佈紙）的色域，下列敘述何者正確？", "opts": ["印刷色域完全落在 sRGB 之內", "兩者互不完全涵蓋；印刷在青綠區可超出 sRGB，因此攝影出版常用 Adobe RGB 作為工作空間", "sRGB 色域完全落在印刷色域之內", "印刷色域只由油墨決定，與紙張無關"], "explain": "顯示器色域在 xy 圖上是三角形，印刷是多邊形，兩者交錯。青綠區印刷較大，所以出版流程偏好色域較大的 Adobe RGB。紙張的白度與吸墨性也會影響印刷色域。", "trap": "「螢幕比較鮮豔，所以一定包含印刷」是學生最常見的直覺。", "src": "科目三指引 2.3（第 2-48 頁）；科目二指引 2.4", "fam": "L13-2016", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "B"}, {"id": "L13-2017", "codes": ["L13105", "L13206", "L13202"], "diff": "難", "level": "分析", "stem": "紡織廠的兩批布：深藍布與淺灰布相對於各自的標準，ΔE*ab 都是 1.5，但目視時淺灰布的差異明顯得多。下列處置何者最適當？", "opts": ["改用 CIEDE2000 評估並採紡織常用的 (kL, kC, kH) = (2, 1, 1)，再於 D65、約 1000 lx、中灰背景的燈箱下目視確認", "ΔE*ab 相同代表視覺差異相同，兩批都直接放行", "改用 CIEDE2000，並採 (kL, kC, kH) = (1, 1, 1)，因為紡織業對明度差最敏感", "改用 xy 色度差判定，因為 xy 比 CIELAB 更均勻"], "explain": "CIELAB 並不完全均勻：人眼對低彩度色的色差較敏感，所以 ΔE*ab 相同不代表視覺差異相同。CIEDE2000 以權重修正；紡織取 kL = 2，放寬明度差。數值之外仍要在標準條件下目視確認。", "trap": "kL = 2 的意義是「降低明度差的權重」；xy 是最不均勻的色度圖，是反向誘答。", "src": "科目三指引 2.2（第 2-39～2-40 頁）；科目二指引 2.1", "fam": "L13-2017", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115考前模擬v1", "diag": false, "ans": "A"}, {"id": "L13-2018", "codes": ["L13302", "L13303", "L13305"], "diff": "難", "level": "分析", "stem": "攝影師交來嵌入 Adobe RGB 描述檔的商品照，設計師的 Photoshop 工作空間預設為 sRGB，印刷廠指定 ISO Coated Fogra39。下列流程何者最正確？", "opts": ["開檔時捨棄嵌入描述檔並「指定」為 sRGB，統一工作空間後再送印", "直接以「指定描述檔」把檔案標成 Fogra39，數值不變最安全", "開檔時保留嵌入描述檔編修，輸出前以「轉換為描述檔」轉到 Fogra39 並依內容選演色意圖，搭配軟式打樣檢查", "把 RGB 數值依 C = 255 − R 的方式換算成 CMYK 後送印"], "explain": "「指定」只改變數值的解讀，同一組數值會看起來不同；「轉換」才會透過 PCS 把數值換成目標裝置的數值，讓外觀盡量一致。嵌入描述檔要保留，輸出時再轉換。", "trap": "「指定」與「轉換」的差別是 Photoshop 色彩管理最常見的失誤；最後一個選項是沒有色彩管理的公式換算。", "src": "徐明景簡報（Photoshop 實務應用）；科目二指引 2.4", "fam": "L13-2018", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "C"}, {"id": "L13-2019", "codes": ["L13101", "L13102", "L13202"], "diff": "難", "level": "應用", "stem": "對色桌只有一盞點光源，距檯面 2 m 時照度為 250 lx。要達到 CIE 建議的目視色差評估條件，下列調整何者正確？", "opts": ["把燈移到距檯面 0.5 m（照度約 1000 lx），其他條件不變", "把燈移到距檯面 1 m（照度約 1000 lx），使用約 6500 K、高演色性的光源，背景用 L*≈50 的中灰", "把燈移到距檯面 1.41 m（照度約 1000 lx），使用約 6500 K 光源", "把燈移到距檯面 1 m，改用 2700 K 暖白光以降低眼睛疲勞"], "explain": "照度與距離平方成反比：2 m→1 m，照度變為 4 倍，250 × 4 = 1000 lx。CIE 建議的色差觀看條件為 D65、約 1000 lx、L*≈50 中灰背景。", "trap": "0.5 m 是以「線性反比」誤算（實際約 4000 lx）；1.41 m 只會得到 500 lx；2700 K 違反 D65 條件。", "src": "科目三指引 1.1（第 2-5 頁）、2.2（第 2-40 頁）", "fam": "L13-2019", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115考前模擬v1", "diag": false, "ans": "B"}, {"id": "L13-2020", "codes": ["L13304", "L13204", "L13105"], "diff": "難", "level": "分析", "stem": "電商攝影棚要建立相機色彩校正流程，讓商品照在 sRGB 螢幕上的顏色準確。下列做法何者最合理？", "opts": ["拍攝 ECI2002 導表建立相機描述檔，再以 RGB 數值差評估準確度", "拍攝 ISO 12233 導表建立相機描述檔，再以 ΔE 評估", "直接使用 JPEG 與自動白平衡，以人眼覺得好看為準", "在標準照明下拍攝 ColorChecker Classic 24 色導表，以 RAW 建立色彩校正矩陣（或描述檔）轉到 sRGB，再以各色塊的 CIELAB ΔE 評估準確度"], "explain": "相機色彩校正的標準導表是 ColorChecker（24 色或 SG）；ECI2002 是 CMYK 印刷導表，ISO 12233 用於解像力。評估要用裝置無關的 ΔE，不能用裝置相關的 RGB 差值。", "trap": "三種導表名稱的錯置，加上用 RGB 差值評估，檢查學生是否分得清裝置相關與裝置無關。", "src": "科目三指引 2.3（第 2-42、2-45 頁）", "fam": "L13-2020", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "D"}, {"id": "D-01", "codes": ["L11102"], "dom": "D1", "diff": "易", "level": "知識", "stem": "一般所稱的「紅綠色盲」（第 1、2 型色覺異常），主要原因是？", "opts": ["S 錐狀細胞缺乏", "桿狀細胞缺乏", "L 或 M 錐狀細胞缺乏或異常", "大腦視覺皮質受損"], "explain": "第 1 型（protan）缺 L、第 2 型（deutan）缺 M，都會混淆紅與綠；第 3 型（tritan）缺 S，混淆藍與黃，比例很少。", "trap": "S 錐細胞對應第 3 型；中樞性色盲確實存在但不是主因。", "src": "科目一指引 1.2（第 2-8 頁）", "fam": "cvd", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "C"}, {"id": "D-02", "codes": ["L11106"], "dom": "D3", "diff": "易", "level": "理解", "stem": "色料三原色中，青（C）與洋紅（M）等量混合，理論上會得到什麼顏色？", "opts": ["紅", "綠", "黑", "藍"], "explain": "青吸收紅光、洋紅吸收綠光，剩下藍光，所以 C + M = 藍。", "trap": "M + Y = 紅、C + Y = 綠、三色相加 = 黑，三個誘答都是減法混色的其他組合。", "src": "科目一指引 1.6（第 2-23 頁）", "fam": "D-02", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "D"}, {"id": "D-03", "codes": ["L11105"], "dom": "D2", "diff": "易", "level": "理解", "stem": "NCS 色彩標記 S 2030-Y70R，下列解讀何者正確？", "opts": ["含白度 50%；色相由 30% 黃與 70% 紅組成", "含白度 50%；色相由 70% 黃與 30% 紅組成", "含白度 30%；色相由 30% 黃與 70% 紅組成", "含黑度 30%、彩度 20%"], "explain": "20 = 含黑度、30 = 彩度，含白度 = 100 − 20 − 30 = 50。Y70R 表示從黃往紅走 70%，即 30% 黃、70% 紅。", "trap": "Y70R 的百分比是指「後面那個主色」，最常被讀反。", "src": "科目一指引 1.5；科目二指引 1.2（第 2-10～2-11 頁）", "fam": "ncs", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "A"}, {"id": "D-04", "codes": ["L11303"], "dom": "D4", "diff": "易", "level": "理解", "stem": "同一個綠色被極細的紅色線條或藍色線條切割後，看起來分別偏紅或偏藍。這是哪一種現象？", "opts": ["同時對比", "色彩同化", "繼時對比", "色彩恆常性"], "explain": "色塊被切成極細小面積時，鄰近色會互相趨近，這是同化；面積大時則會出現相反的同時對比。", "trap": "同時對比與同化效果方向相反，關鍵在面積大小。", "src": "科目一指引 3.3（第 2-51 頁）", "fam": "assim", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "B"}, {"id": "D-05", "codes": ["L13103"], "dom": "D6", "diff": "易", "level": "知識", "stem": "CIELAB 色彩空間中，−b* 方向代表哪一種色彩傾向？", "opts": ["黃", "綠", "紅", "藍"], "explain": "+a* 紅、−a* 綠、+b* 黃、−b* 藍，對應對立色理論的紅綠與黃藍兩軸。", "trap": "只是把四個方向交錯排列。", "src": "科目三指引 1.4（第 2-23 頁）", "fam": "D-05", "type": "mc", "subj": "L13", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "D"}, {"id": "D-06", "codes": ["L11201"], "dom": "D3", "diff": "易", "level": "應用", "stem": "RGB 影像每個通道以 8 bit 記錄，理論上可表現多少種顏色？", "opts": ["16,777,216", "65,536", "262,144", "1,073,741,824"], "explain": "每通道 2⁸ = 256 階，三通道為 256³ = 2²⁴ = 16,777,216 種組合。", "trap": "65,536 = 2¹⁶（把位元數看成 16）；262,144 = 2¹⁸（每通道 6 bit）；1,073,741,824 = 2³⁰（每通道 10 bit）。誘答都是位元數判讀錯誤的結果，量級相近，不能靠「看起來最大」猜答案。", "src": "科目一指引 2.1（第 2-25～2-26 頁）", "fam": "bitdepth", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "A"}, {"id": "D-07", "codes": ["L12102"], "dom": "D2", "diff": "易", "level": "知識", "stem": "孟塞爾標記 10GY 5/10，下列解讀何者正確？", "opts": ["色相 10GY、彩度 5、明度 10", "色相 5GY、明度 10、彩度 5", "色相 10GY、明度 5、彩度 10", "色相 GY、明度 10、彩度 5"], "explain": "孟塞爾標記的順序為「色相 明度/彩度」，斜線前是明度、後是彩度。", "trap": "明度與彩度的位置對調是最常見的錯誤。", "src": "科目二指引 1.2（第 2-7 頁）；李文淵簡報", "fam": "D-07", "type": "mc", "subj": "L12", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "C"}, {"id": "D-08", "codes": ["L13303"], "dom": "D7", "diff": "易", "level": "理解", "stem": "為什麼不同軟體、不同作業系統，都能讀取同一個色彩描述檔（.icc／.icm）並正確轉換色彩？", "opts": ["因為所有裝置的 RGB 數值意義都相同", "描述檔採用國際色彩聯盟（ICC）制定的標準格式", "因為描述檔內容就是一張 RGB 截圖", "因為描述檔由國際照明委員會（CIE）為每台裝置分別製作"], "explain": "ICC 制定描述檔的標準格式，所以成為業界通用的色彩資訊交換標準；描述檔內容是裝置訊號與 PCS 之間的對應關係。", "trap": "CIE 制定色度學與 CIELAB，不負責描述檔格式。", "src": "徐明景簡報；科目一指引 2.6", "fam": "D-08", "type": "mc", "subj": "L13", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "B"}, {"id": "D-09", "codes": ["L11103", "L11104"], "dom": "D1", "diff": "中", "level": "應用", "stem": "餐廳希望營造溫暖氛圍，同時讓食物顏色看起來自然可口。下列照明規格何者最合適？", "opts": ["約 6500 K、Ra ≥ 90，因為色溫越高越溫暖", "約 2700 K、Ra 約 70，色溫比演色性重要", "約 9300 K、Ra 約 80", "約 2700–3000 K、Ra ≥ 90"], "explain": "低色溫偏黃紅，給人溫暖感；高演色性讓物體顏色忠實呈現。色溫與演色性是兩個獨立指標，要分別指定。", "trap": "「色溫越高越溫暖」是把物理溫度與心理冷暖搞混的經典錯誤。", "src": "科目一指引 1.3（第 2-10 頁）、1.4（第 2-14 頁）", "fam": "lightspec", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "D"}, {"id": "D-10", "codes": ["L11201", "L11206"], "dom": "D7", "diff": "中", "level": "理解", "stem": "關於 sRGB 與 Adobe RGB，下列敘述何者「錯誤」？", "opts": ["兩者都定義了 RGB 訊號與 CIE 色度值的對應", "sRGB 色域較大，較適合專業商業攝影與高品質印刷", "Adobe RGB 採用更鮮豔的綠色原色", "網頁圖檔一般建議使用 sRGB"], "explain": "Adobe RGB 的色域比 sRGB 大，尤其在青綠區，因此較適合商業攝影與高品質印刷；sRGB 是網頁預設。", "trap": "把兩者的大小關係對調，同時考「何者錯誤」的閱讀。", "src": "科目一指引 2.1（第 2-27 頁）", "fam": "srgb", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "B"}, {"id": "D-11", "codes": ["L11302", "L11403"], "dom": "D4", "diff": "中", "level": "應用", "stem": "戶外指標要在遠距離快速辨讀文字。下列文字／背景配色中，可視度最高的是？", "opts": ["黃底黑字", "紅底綠字（明度相近）", "黃底白字", "藍底黑字"], "explain": "可視度主要靠明度對比：黃底明度高、黑字明度最低，差距最大。只有色相差、沒有明度差的配色，遠距離最難辨識。", "trap": "紅底綠字色相差很大但明度相近，用來檢查學生是否知道「色相對比不等於可視度」。", "src": "科目一指引 3.2（第 2-45～2-46 頁）", "fam": "visib", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "A"}, {"id": "D-12", "codes": ["L11402", "L12201"], "dom": "D4", "diff": "中", "level": "應用", "stem": "兩色同屬 PCCS 鮮豔色調（v），色相角相差 150°。這組配色屬於？", "opts": ["色調差配色法（tone on tone），強色相對比", "鄰近色配色法（tone in tone），弱色相對比", "色相差配色法（tonal），強色相對比", "色相差配色法（tonal），中色相對比"], "explain": "同色調、不同色相 → 色相差配色法。色相角差 ≥ 120° 為強對比、60°–120° 為中、10°–60° 為弱。", "trap": "考兩層判斷：配色法類型，以及色相對比強度的分級門檻。", "src": "科目二指引 2.3（第 2-34 頁）", "fam": "D-12", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "C"}, {"id": "D-13", "codes": ["L12102", "L13103"], "dom": "D2", "diff": "中", "level": "應用", "stem": "某色 CIELAB = (60, 0, −40)，換成 L*C*h 表示，下列何者正確？", "opts": ["C* = 40，h = 90°，屬黃色", "C* = −40，h = 270°，屬藍色", "C* = 40，h = 270°，屬藍色", "C* = 40，h = 180°，屬綠色"], "explain": "C* = √(0² + 40²) = 40，彩度不會是負值；落在 −b* 軸上，h = 270°，為藍色。", "trap": "彩度是距離，不可能為負；把 −b* 當成 90° 是方向判斷錯誤。", "src": "科目二指引 1.2（第 2-12～2-13 頁）", "fam": "lch", "type": "mc", "subj": "L12", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "C"}, {"id": "D-14", "codes": ["L13305", "L11206"], "dom": "D7", "diff": "中", "level": "應用", "stem": "將簡報裡鮮豔的商業長條圖由 RGB 轉為 CMYK 輸出，希望顏色維持鮮明、色相略有偏移可以接受。應選哪一種演色意圖？", "opts": ["飽和度式（saturation）", "感應式（perceptual）", "相對色度式（relative colorimetric）", "絕對色度式（absolute colorimetric）"], "explain": "飽和度式以保持鮮豔度為優先，明度與色相可能改變，適合商業圖表。感應式適合自然影像；色度式重視色度值準確，適合打樣。", "trap": "與 A 卷第 14 題（自然影像用感應式）對照，兩題一起答對才代表真正理解四種意圖的適用情境。", "src": "科目一指引 2.6（第 2-36 頁）", "fam": "intent", "type": "mc", "subj": "L13", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "A"}, {"id": "D-15", "codes": ["L11301", "L11205", "L12201"], "dom": "D5", "diff": "中", "level": "應用", "stem": "為銀髮族保健品做色彩計畫。下列哪一種做法最符合色彩計畫的「科學化」特性？", "opts": ["依設計師個人偏好決定主色，再交由客戶確認", "先對目標族群進行色彩意象與偏好調查，再以色彩體系標記選出主色", "直接套用今年的國際流行色", "以 3D 彩現圖中最好看的顏色作為標準色"], "explain": "科學化指依客觀調查資料規劃色彩，而不是個人喜好；以色彩體系標記則對應「系統化」。", "trap": "三個誘答分別代表主觀喜好、未經驗證的趨勢，以及錯誤的標準色依據。", "src": "科目一指引 2.5、3.1；科目二指引 2.1（第 2-15 頁）", "fam": "plan4", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "B"}, {"id": "D-16", "codes": ["L13104", "L13101"], "dom": "D6", "diff": "中", "level": "理解", "stem": "要量測（甲）螢幕白點的色度與亮度、（乙）印刷色塊的 CIELAB 值，下列儀器與校正方式的搭配何者正確？", "opts": ["甲用分光光度儀（白板校正）；乙用分光輻射儀（黑歸零）", "甲乙都用光澤計（高光澤黑玻璃校正）", "甲用濃度計；乙用色度計，兩者都不需校正", "甲用分光輻射儀（使用前黑歸零）；乙用分光光度儀（使用前白板校正）"], "explain": "光源色（螢幕）用分光輻射儀量 SPD，使用前做黑歸零；表面色（印刷品）用分光光度儀量光譜反射率，使用前做白板校正。", "trap": "測光源色與表面色的儀器互換，是量測單元最常見的錯誤。", "src": "科目三指引 2.1（第 2-31～2-32、2-37 頁）", "fam": "calib", "type": "mc", "subj": "L13", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "D"}, {"id": "D-17", "codes": ["L11106", "L11207", "L13203"], "dom": "D3", "diff": "難", "level": "分析", "stem": "單晶片 DLP 投影機以色輪快速依序投射紅、綠、藍光，觀眾看到全彩影像；但有人快速轉動視線時，會在白色邊緣看到紅綠藍分離的「彩虹紋」。下列解釋何者正確？", "opts": ["DLP 屬於時序加法混色，依靠視覺時間解析力不足；眼球快速移動讓三色落在視網膜不同位置，整合失敗", "DLP 屬於並置加法混色，彩虹紋是子畫素太大造成", "DLP 屬於減法混色，彩虹紋是色輪濾鏡重疊造成", "彩虹紋是色彩同化現象，與混色方式無關"], "explain": "單晶片 DLP 依時間輪流呈現 RGB，靠時間解析力不足在視覺上合成。視線快速移動時，前後出現的色光落在視網膜不同位置，就會看到分離的色邊。", "trap": "把 LCD 的並置混色、濾鏡的減法混色套到 DLP，檢查學生能否把混色原理與具體裝置對應起來。", "src": "科目一指引 1.6（第 2-22 頁）、2.7（第 2-39 頁）；陳鴻興簡報", "fam": "dlp", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "A"}, {"id": "D-18", "codes": ["L12201", "L12102", "L11205"], "dom": "D5", "diff": "難", "level": "分析", "stem": "3C 產品外殼色彩計畫完成後要交給代工廠量產。下列哪一種交付方式最能確保色彩一致？", "opts": ["提供 3D 彩現圖與螢幕截圖的 RGB 色碼", "提供 CMYK 數值，因為印刷數值是國際通用標準", "只提供色名，例如「晨霧銀」，由工廠自行調色", "實體標準色樣＋裝置無關標記（如 CIELAB 值）＋允許色差 ΔE，並註明在標準光源下目視確認"], "explain": "色彩計畫要以色票（標準色樣）與色彩標記作為生產依據，並以 CIELAB 色差訂允差。彩現圖受光影、材質影響；RGB 與 CMYK 都是裝置相關色，不能當標準色依據。", "trap": "RGB 與 CMYK 都「看起來是數字」，用來檢查學生是否真正理解裝置相關與裝置無關的差別。", "src": "科目二指引 2.1（第 2-17、2-19 頁）、2.4（第 2-40～2-41 頁）", "fam": "D-18", "type": "mc", "subj": "L12", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "D"}, {"id": "D-19", "codes": ["L13105", "L13103"], "dom": "D6", "diff": "難", "level": "分析", "stem": "兩個近灰色樣本的 (a*, b*) 分別為 (1, 0) 與 (0, 1)，明度相同。下列敘述何者正確？", "opts": ["兩者色相角差 90°，代表視覺上色相差異極大", "ΔE*ab = 90", "ΔE*ab ≈ 1.4，幾乎都來自色相差 ΔH*，但絕對量很小，視覺上差異不大", "色相差 ΔH* 就等於色相角差 Δh = 90°"], "explain": "兩者 C* 都是 1，ΔC* = 0、ΔL* = 0，所以 ΔE*ab = √2 ≈ 1.4，全部是 ΔH*。低彩度色的色相角差可以很大，但 ΔH* 很小，視覺差異也小。", "trap": "色相差 ΔH* 與色相角差 Δh 的區別，是官方指引特別點出的重點。", "src": "科目三指引 1.5（第 2-25 頁）", "fam": "D-19", "type": "mc", "subj": "L13", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "C"}, {"id": "D-20", "codes": ["L11102", "L11302", "L12201"], "dom": "D5", "diff": "難", "level": "分析", "stem": "捷運路線圖要讓色覺異常者也能辨識各條路線。下列配色策略何者最恰當？", "opts": ["提高所有路線的彩度，讓紅綠更鮮豔", "除了色相差，也拉開相鄰路線的明度差，並加上路線代號、文字或線型等非色彩線索", "全部改用 tone in tone 配色，畫面更協調", "只要避免使用紅色即可"], "explain": "第 1、2 型色覺異常者難以分辨紅綠色相，但明度差仍可辨識。通用設計原則是不只靠顏色傳遞資訊，要搭配明度差與符號等冗餘線索。", "trap": "提高彩度無法解決色相混淆；tone in tone 反而縮小差異；只避開紅色忽略了綠、棕等混淆組合。", "src": "科目一指引 1.2、3.2；謝翠如簡報（通用設計）", "fam": "D-20", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "B"}, {"id": "L11-3001", "codes": ["L11101"], "diff": "易", "level": "理解", "stem": "捷運路網圖以不同顏色區分各條路線，主要運用了色彩的哪一種功能？", "opts": ["指示性功能", "象徵性功能", "情緒影響功能", "美感功能"], "explain": "以色名或色相標記、區分類別，是指示性功能，常見於標誌與資訊視覺化。", "trap": "路線色有時也帶象徵意義，但「區分路線」的主要目的是指示。", "src": "科目一指引 1.1（第 2-2 頁）", "fam": "L11-3001", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3002", "codes": ["L11102"], "diff": "易", "level": "知識", "stem": "關於視網膜上的桿狀細胞，下列敘述何者正確？", "opts": ["主要集中在中央小窩，負責辨識細節", "分為 L、M、S 三種", "主司暗視覺，敏感度高，但無法產生色彩訊號", "在明亮環境下負責色彩視覺"], "explain": "桿狀細胞多分布於視網膜周邊，在低亮度下作用，敏感度高但沒有色彩訊號。集中於中央小窩、分三型的是錐狀細胞。", "trap": "三個誘答都是錐狀細胞的特性。", "src": "科目一指引 1.2（第 2-5～2-6 頁）", "fam": "rodcone", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-3003", "codes": ["L11102", "L11303"], "diff": "中", "level": "理解", "stem": "凝視紅色圖形 30 秒後轉看白紙，會看到青綠色的殘像。下列哪一個理論最能解釋這個現象？", "opts": ["三色論：L 錐狀細胞數量不足", "色彩同化：鄰近色彩相互趨近", "加法混色：紅光與白光混合成青綠", "對立色（拮抗）理論：紅—綠通道長時間被單向刺激後產生反向反應"], "explain": "三色論說明錐狀細胞接收訊號，對立色理論說明後續處理成紅綠、黃藍、明暗通道。補色殘像是對立通道疲勞後的反向反應，三色論無法解釋。", "trap": "指引明確指出三色論無法解釋後像，這是兩理論分工的核心考點。", "src": "科目一指引 1.2（第 2-7 頁）、3.3", "fam": "after", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-3004", "codes": ["L11103"], "diff": "易", "level": "理解", "stem": "博物館不能用紫外線燈或紅外線加熱燈來讓觀眾看清楚展品的顏色，最主要的原因是？", "opts": ["兩者的色溫太低", "兩者的波長都落在人眼可見光（約 380–780 nm）之外，無法引起色彩感覺", "兩者的演色指數太高", "兩者都屬於線狀光譜"], "explain": "紫外線比紫光短、紅外線比紅光長，人眼無法感應，所以不能提供色彩感覺。（此外紫外線與熱也可能傷害展品。）", "trap": "", "src": "科目一指引 1.3；科目三指引 1.1", "fam": "L11-3004", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-3005", "codes": ["L11103", "L11104"], "diff": "中", "level": "應用", "stem": "某生鮮賣場在肉品區使用偏紅光譜的特殊燈具，讓肉看起來更鮮紅。從色彩學角度，下列判斷何者正確？", "opts": ["因為肉看起來更鮮豔，這種燈的演色指數 Ra 一定較高", "只要色溫是 6500 K，演色性就一定好", "光源光譜不會影響物體色，只影響亮度", "這種燈的演色性並不忠實，物體顏色被「美化」而偏離日光下的樣貌"], "explain": "演色性指光源忠實呈現物體顏色的能力，以接近日光的參考光源為準。刻意加強某段光譜讓物體更鮮豔，反而偏離參考，Ra 不一定高。色溫與演色性是兩個獨立指標。", "trap": "「更鮮豔＝演色性更好」是最常見的誤解；科目三指引的例題也考過。", "src": "科目一指引 1.4（第 2-14 頁）；科目三指引 1.5 例題", "fam": "cri", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-3006", "codes": ["L11104"], "diff": "易", "level": "理解", "stem": "在白光照射下，一個紅色物體主要吸收了哪些色光？", "opts": ["綠光與藍光", "紅光", "紅光與綠光", "所有色光都等量吸收"], "explain": "紅色物體反射紅光、吸收綠光與藍光，進入眼睛的剩餘光線形成紅色感覺。", "trap": "把「看到的顏色」誤當成「吸收的顏色」。", "src": "科目一指引 1.4（第 2-13 頁）", "fam": "L11-3006", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3007", "codes": ["L11104", "L11103"], "diff": "中", "level": "應用", "stem": "在只有純藍色光照明的展場中，一顆紅蘋果看起來最可能是什麼樣子？", "opts": ["依然是鮮紅色", "變成紫色", "很暗，接近黑色", "變成白色"], "explain": "紅蘋果主要反射長波長的紅光；純藍光中幾乎沒有紅光可反射，藍光又大多被吸收，所以看起來很暗。物體色取決於光源光譜與物體反射特性的共同作用。", "trap": "「變紫色」是把加法混色（紅光＋藍光）誤用到光源與物體的關係上。", "src": "科目一指引 1.4", "fam": "L11-3007", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-3008", "codes": ["L11104"], "diff": "易", "level": "知識", "stem": "形成色彩感覺的三個要素是？", "opts": ["色相、明度、彩度", "光、物體、視覺系統", "紅、綠、藍", "光源、色料、紙張"], "explain": "色彩由光源、物體（反射、透射、吸收）與觀察者的視覺系統共同形成。色相、明度、彩度是色彩三屬性，不是形成要素。", "trap": "「三要素」與「三屬性」名稱相近，常被混淆。", "src": "科目一指引 1.4（第 2-13 頁）", "fam": "L11-3008", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-3009", "codes": ["L11105"], "diff": "易", "level": "知識", "stem": "PCCS 色彩體系中的「色調」（tone）綜合了哪兩個屬性？", "opts": ["色相與明度", "色相與彩度", "含黑度與含白度", "明度與彩度"], "explain": "PCCS 以「色相＋色調」表示色彩，色調把明度與彩度合為一個概念，例如鮮豔（v）、淺（lt）、深（dp），便於設計溝通。", "trap": "含黑度、含白度是 NCS 的屬性。", "src": "科目一指引 1.5（第 2-19 頁）；科目二指引 1.1", "fam": "pccs", "type": "mc", "subj": "L11", "dom": "D2", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-3010", "codes": ["L11105", "L12102"], "diff": "中", "level": "理解", "stem": "比較孟塞爾與 NCS 兩個色彩體系，下列敘述何者「錯誤」？", "opts": ["孟塞爾以明度與彩度兩軸定位同色相的色彩", "NCS 以含白度、含黑度與彩度定位同色相的色彩，三者總和為 100", "兩者都以紅、黃、綠、藍、紫五個主色構成色相環", "NCS 依據對立色理論，以紅、黃、綠、藍四色構成色相環"], "explain": "孟塞爾色相環有 R、Y、G、B、P 五個主色；NCS 依心理四原色只有 R、Y、G、B 四色。", "trap": "把孟塞爾的五主色套到 NCS 上，考兩體系的根本差異。", "src": "科目一指引 1.5；科目二指引 1.2（第 2-10 頁）", "fam": "L11-3010", "type": "mc", "subj": "L11", "dom": "D2", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-3011", "codes": ["L11106"], "diff": "易", "level": "理解", "stem": "下列哪一個例子屬於「並置加法混色」？", "opts": ["印象派點描畫與印刷網點", "兩層彩色濾鏡疊在一起", "兩種顏料在調色盤上混合", "快速旋轉的雙色陀螺"], "explain": "並置混色是極小面積的色點並排，超出眼睛空間解析力而混合，例如點描與網點。濾鏡疊合與顏料混合是減法混色；旋轉陀螺是時序混色。", "trap": "三個誘答分別對應減法混色與時序混色。", "src": "科目一指引 1.6（第 2-22 頁）", "fam": "L11-3011", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3012", "codes": ["L11106", "L11201"], "diff": "中", "level": "理解", "stem": "在螢幕上把紅光與綠光等量混合會看到黃色；但在調色盤上把紅色與綠色顏料等量混合，結果最可能是？", "opts": ["黃色", "暗濁的灰褐色", "白色", "比原來更亮的橙色"], "explain": "螢幕是加法混色，紅光＋綠光＝黃。顏料是減法混色，紅與綠近似互補，混合後吸收大部分光，得到暗色。", "trap": "這是官方指引的例題概念，用來確認學生分得清加法與減法混色的情境。", "src": "科目一指引 1.6（第 2-24 頁）", "fam": "L11-3012", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-3013", "codes": ["L11201"], "diff": "易", "level": "理解", "stem": "在繪圖軟體的 HSB 選色器中，只拖動 S（Saturation）滑桿，顏色會怎麼變化？", "opts": ["色相改變，鮮豔程度不變", "色相不變，鮮豔程度改變", "只有明暗改變", "顏色變成 CMYK 色彩"], "explain": "HSB 以色相（H）、飽和度（S）、亮度（B）模擬知覺屬性；只調 S 時色相固定，顏色由灰往鮮豔變化。", "trap": "", "src": "科目一指引 2.1、2.4", "fam": "L11-3013", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-3014", "codes": ["L11202", "L11204"], "diff": "中", "level": "應用", "stem": "攝影常用的「18% 灰卡」反射率只有 18%，卻被視為中間灰。依 CIELAB 明度公式 L* ＝ 116 (Y/Yn)^(1/3) − 16，它的 L* 約為多少？", "opts": ["約 50", "約 18", "約 82", "約 9"], "explain": "(0.18)^(1/3) ≈ 0.565，116 × 0.565 − 16 ≈ 49.5。人眼的明度感覺與亮度呈非線性關係，所以 18% 反射率在感覺上約在中間。", "trap": "18 是直接把反射率當明度，正是心理物理學要修正的線性直覺。", "src": "科目一指引 2.2（第 2-28 頁）", "fam": "L11-3014", "type": "mc", "subj": "L11", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3015", "codes": ["L11203"], "diff": "易", "level": "理解", "stem": "評估色彩複製品質時，下列敘述何者正確？", "opts": ["只能用目視判斷，不能量化", "只能用色差數值判斷，與用途無關", "原稿與複製品的色差越大，品質越好", "可用 CIE 色差公式做客觀評估，也可依用途與偏好做主觀評估"], "explain": "色彩複製品質可以客觀（色差公式）或主觀（使用目的、觀者偏好、客戶需求）評估，兩者常並用。", "trap": "單一評估方式的絕對化敘述。", "src": "科目一指引 2.3（第 2-30 頁）", "fam": "L11-3015", "type": "mc", "subj": "L11", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-3016", "codes": ["L11206"], "diff": "易", "level": "知識", "stem": "下列何者屬於「裝置無關色」？", "opts": ["sRGB 數值", "印刷 CMYK 網點百分比", "CIELAB", "螢幕的 RGB 訊號值"], "explain": "裝置無關色以人類視覺定義，例如 CIELAB、CIEXYZ。RGB、CMYK 數值會隨裝置不同而呈現不同顏色，屬裝置相關色。", "trap": "sRGB 雖是標準化空間，但在色彩管理的分類中仍屬裝置相關（RGB）系統。", "src": "科目一指引 2.6（第 2-35 頁）", "fam": "L11-3016", "type": "mc", "subj": "L11", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-3017", "codes": ["L11207", "L11106"], "diff": "中", "level": "理解", "stem": "比較 OLED 與 LCD 顯示器，下列敘述何者正確？", "opts": ["LCD 自發光，OLED 需要背光模組", "OLED 自發光，理論上不需背光模組；兩者都以紅綠藍子畫素並置混色", "OLED 以減法混色呈現全彩", "LCD 以時序混色呈現全彩"], "explain": "OLED 的有機發光層通電後自行發光，可省去背光與部分濾光片，因此更輕薄。兩者都以 RGB 子畫素並置的加法混色呈現全彩。", "trap": "考「自發光」與「混色方式」兩個面向。", "src": "科目一指引 2.7（第 2-38～2-39 頁）", "fam": "L11-3017", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-3018", "codes": ["L11301"], "diff": "易", "level": "理解", "stem": "從日光燈下走到夕陽下，白紙看起來仍然是白色。這主要是哪一種現象？", "opts": ["色彩恆常性", "色彩同化", "繼時對比", "條件等色"], "explain": "色彩恆常性指視覺系統會適應或補償光源變化，維持穩定的物體色感覺；相機的白平衡是在模仿這個機制。", "trap": "條件等色是兩個光譜不同的物體在某光源下等色，與單一物體跨光源的穩定感不同。", "src": "科目一指引 3.1（第 2-41 頁）", "fam": "L11-3018", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3019", "codes": ["L11302", "L11303"], "diff": "中", "level": "應用", "stem": "海報上明度相近的高彩度紅字放在綠底上，邊界顯得模糊、閃爍。下列哪一種改善方式最有效？", "opts": ["把紅字的彩度再提高", "把綠底換成同明度的藍色", "把字體縮小，讓同化效果中和閃爍", "在紅字外加黑色或白色描邊，並拉開字與底的明度差"], "explain": "中高彩度、明度相近的兩色相鄰會產生色滲，以中性色隔開可降低；拉開明度差則能提高可視度。", "trap": "提高彩度或換成同明度的另一色相，都無法解決明度差不足的問題。", "src": "科目一指引 3.2、3.3（第 2-49 頁）", "fam": "bleed", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-3020", "codes": ["L11404", "L11401"], "diff": "中", "level": "應用", "stem": "一個文創品牌希望包裝呈現「沉穩、復古、樸素」的感覺。依「以彩度為主的配色」原則，下列哪一種方向最合適？", "opts": ["選用高彩度的同彩度組合", "選用無彩色搭配高彩度螢光色", "選用中低彩度的同彩度組合", "選用互補色、高彩度強對比"], "explain": "同彩度配色中，高彩度組呈現活潑年輕感，中低彩度組則偏向穩重、成熟、樸素、復古。", "trap": "高彩度與強對比會傳達相反的意象。", "src": "科目一指引 4.4（第 2-57 頁）", "fam": "L11-3020", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-3021", "codes": ["L11403", "L11302", "L11102"], "diff": "難", "level": "分析", "stem": "一份資訊圖表以「綠→黃→紅」表示風險高低，但常被黑白影印，讀者中也有紅綠色覺異常者。下列修正方式何者最恰當？", "opts": ["保持原色，只把飽和度調高", "改用同明度的紅、綠、藍三色區分等級", "改用明度單向漸變的色階（由淺到深），讓灰階與色覺異常者都能依明度判讀高低", "加上更多色相，例如七色彩虹色階"], "explain": "明度差在灰階列印與紅綠色覺異常時都仍然存在；單向明度漸變也最符合「數值越高、越深」的直覺。只靠色相差的色階兩種情境都會失效。", "trap": "彩虹色階的明度不單調，是資訊視覺化常見的錯誤。", "src": "科目一指引 1.2、3.2、4.3；謝翠如簡報", "fam": "L11-3021", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-3022", "codes": ["L11303", "L11205"], "diff": "難", "level": "分析", "stem": "服飾品牌開發細格紋布料：小色樣上的格紋與底色看起來分明，但做成整件外套遠看時，整體色調明顯偏向格紋線色。從色彩計畫角度，下列判斷與做法何者最恰當？", "opts": ["這是色彩同化，觀看距離越遠、線條越細越明顯；應以全尺寸樣品在實際觀看距離確認", "這是同時對比，只要把格紋線加粗就會更明顯", "這是條件等色，應換光源量測", "小色樣已確認過，量產不會有差異"], "explain": "細小面積的色彩會與鄰近色互相趨近（同化），遠看時線條在視網膜上更細，效果更強。指引也提醒最終色彩要在全尺寸物體上確認。", "trap": "同時對比與同化效果相反，關鍵在面積與觀看距離。", "src": "科目一指引 3.3（第 2-51 頁）；科目二指引 2.1 注意事項", "fam": "L11-3022", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3023", "codes": ["L11206", "L11203", "L11204"], "diff": "難", "level": "分析", "stem": "設計師在 sRGB 螢幕上調出一個很鮮豔的翠綠色做為主視覺，印刷後卻明顯變暗變濁。下列解釋與做法何者最恰當？", "opts": ["印刷廠油墨品質不良，換一家即可", "該色超出 CMYK 印刷色域；應先開軟式打樣預覽，並以印刷色票或專色確認可實現的顏色", "螢幕亮度太低，調亮螢幕後印刷就會一致", "把 RGB 數值直接寫入 CMYK 欄位即可避免偏色"], "explain": "RGB 與 CMYK 色域互不完全涵蓋，鮮豔綠色常在印刷色域外。設計階段就要用軟式打樣與實體色票確認，必要時改用專色。", "trap": "換廠或調螢幕都沒有處理色域與色彩管理的根本問題。", "src": "科目一指引 2.6；科目二指引 2.4（第 2-39～2-40 頁）", "fam": "L11-3023", "type": "mc", "subj": "L11", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-3024", "codes": ["L11402"], "diff": "易", "level": "理解", "stem": "以色相為主的配色中，選用互補色相（色相差很大）的搭配，通常會產生什麼效果？", "opts": ["協調柔和", "單純一致", "沉穩樸素", "對比強烈"], "explain": "色相差大（如補色）產生對比效果；選鄰近色相則產生協調效果。", "trap": "協調是鄰近色相的效果。", "src": "科目一指引 4.2（第 2-55 頁）", "fam": "L11-3024", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-3025", "codes": ["L11403"], "diff": "易", "level": "理解", "stem": "選擇「不同色相、相同明度」的色彩組合，在高明度組與低明度組分別會給人什麼感覺？", "opts": ["高明度組輕快，低明度組沉穩", "高明度組沉穩，低明度組輕快", "兩者都很刺激", "明度與感覺無關"], "explain": "依指引，同明度配色中，高明度組感覺輕快，低明度組感覺沉穩。", "trap": "與彩度配色（活潑 vs 樸素）的效果互相對照。", "src": "科目一指引 4.3（第 2-56 頁）", "fam": "L11-3025", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3026", "codes": ["L11201", "L11106", "L11207"], "diff": "難", "level": "分析", "stem": "一張天空藍漸層的海報，在一般 8-bit 螢幕上出現一圈圈明顯的「色帶」（banding）。下列解釋與改善方式何者最恰當？", "opts": ["螢幕的色溫太高；把白點改成 5000 K 就會消失", "sRGB 色域太小；改用 CMYK 即可解決", "漸層跨度大而色階數有限，相鄰階的差異被看出來；可提高色彩深度（如 16-bit 編修），或加入細微雜訊（dithering），以並置混色讓過渡更平順", "這是同時對比，只要在色帶之間加黑框即可"], "explain": "8-bit 每通道只有 256 階，緩慢的大面積漸層會出現可辨識的階差。提高位元深度可增加階數；dithering 用細小雜點讓眼睛把相鄰階混合（並置混色），在不增加位元數的情況下減少色帶。", "trap": "色帶是階調（色彩深度）問題，不是色溫或色域問題。", "src": "科目一指引 1.6、2.1（第 2-25～2-26 頁）、2.7", "fam": "L11-3026", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L12-3001", "codes": ["L12101"], "diff": "易", "level": "理解", "type": "seq", "ans": ["31", "03", "25", "14", "01"], "stem": "請將色票卡上的票號 25、31、01、03、14 依「明度」由低到高排列，依序填入票號。【全對全錯】", "explain": "這五張同色相、同彩度，只有明度不同。由低到高：31（5PB 3/4）、03（5PB 4/4）、25（5PB 5/4）、14（5PB 6/4）、01（5PB 7/4）。", "trap": "只變動一個屬性，是三屬性辨識的基本題。排錯通常是中間三階相鄰兩張對調。", "src": "科目二評鑑內容 L12101；李文淵簡報", "fam": "order-L", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false}, {"id": "L12-3002", "codes": ["L12101"], "diff": "易", "level": "理解", "type": "seq", "ans": ["34", "51", "56", "59", "22"], "stem": "請將票號 56、22、34、59、51 依「明度」由低到高排列。【全對全錯】", "explain": "同為 5G、彩度 4，明度依序為 3、4、6、7、8：34（5G 3/4）、51（5G 4/4）、56（5G 6/4）、59（5G 7/4）、22（5G 8/4）。", "trap": "這組明度間距不等（4 到 6 跳一階），用來檢查學生是否真的在比較明度，而不是靠均勻間距猜順序。", "src": "科目二評鑑內容 L12101", "fam": "order-L", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false}, {"id": "L12-3003", "codes": ["L12101"], "diff": "易", "level": "理解", "type": "seq", "ans": ["26", "54", "46", "10", "52"], "stem": "請將票號 10、26、52、46、54 依「彩度」由低（灰）到高（鮮豔）排列。【全對全錯】", "explain": "同色相、同明度，彩度依序為 2、4、6、8、10。", "trap": "中間三階的彩度差最難分辨。", "src": "科目二評鑑內容 L12101", "fam": "order-C", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false}, {"id": "L12-3004", "codes": ["L12101"], "diff": "易", "level": "理解", "type": "seq", "ans": ["23", "25", "49", "27", "41"], "stem": "請將票號 49、41、23、27、25 依「彩度」由低到高排列。【全對全錯】", "explain": "同為 5PB、明度 5，彩度依序為 2、4、6、8、10。", "trap": "藍紫色系高彩度時看起來偏暗，學生容易把彩度變化誤判成明度變化。", "src": "科目二評鑑內容 L12101", "fam": "order-C", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false}, {"id": "L12-3005", "codes": ["L12101", "L12102"], "diff": "中", "level": "分析", "type": "seq", "ans": ["24", "37", "43", "08", "60"], "stem": "票號 37、60、08、24、43 色相各不相同。請只依「明度」由低到高排列。【全對全錯】", "explain": "明度依序：24（5P 3/6）、37（5Y 4/6）、43（5G 5/6）、08（5R 6/6）、60（5PB 7/6）。", "trap": "黃色常被直覺判為最亮，但 5Y 4/6 是暗橄欖色。這題檢查能否把色相與明度分開判斷。", "src": "科目二評鑑內容 L12101；科目二指引 1.1", "fam": "order-x", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false}, {"id": "L12-3006", "codes": ["L12101", "L12102"], "diff": "中", "level": "分析", "type": "seq", "ans": ["17", "42", "29", "58", "53"], "stem": "票號 58、42、53、17、29 的色相與彩度不完全相同。請只依「明度」由低到高排列。【全對全錯】", "explain": "明度依序：17（5R 3/6）、42（5YR 4/6）、29（10B 5/6）、58（5P 6/6）、53（5YR 7/8）。", "trap": "兩張同為 5YR，但一暗一亮；高彩度的 5YR 7/8 容易讓人以為較暗。", "src": "科目二評鑑內容 L12101", "fam": "order-x", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false}, {"id": "L12-3007", "codes": ["L12102"], "diff": "易", "level": "理解", "type": "one", "ans": ["50"], "stem": "某產品色彩規格為孟塞爾 5Y 8/10。請在色票卡上找出最符合的票號。", "explain": "5Y 8/10：色相 5Y、明度 8、彩度 10，是明亮鮮豔的黃，即 50（5Y 8/10）。卡上相近的 40（5Y 8/4）（彩度較低）、06（5GY 8/10）（偏黃綠）、13（5Y 6/8）（較暗較灰）都是誘答。", "trap": "卡上放了三張只差一個或兩個屬性的黃色。", "src": "科目二指引 1.2", "fam": "find", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false}, {"id": "L12-3008", "codes": ["L12102"], "diff": "易", "level": "理解", "type": "one", "ans": ["27"], "stem": "規格為孟塞爾 5PB 5/8。請在色票卡上找出最符合的票號。", "explain": "5PB 明度 5 的彩度系列在卡上有 /2、/4、/6、/8、/10 五張，答案是 27（5PB 5/8）。", "trap": "要在相鄰彩度階之間做選擇，是讀標記加上判斷彩度的組合。", "src": "科目二指引 1.2", "fam": "find", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false}, {"id": "L12-3009", "codes": ["L12102"], "diff": "易", "level": "理解", "type": "one", "ans": ["35"], "stem": "規格為孟塞爾 5BG 6/4。請在色票卡上找出最符合的票號。", "explain": "答案是 35（5BG 6/4）。卡上還有 5BG 的其他明度階，以及 09（10G 5/4）、30（5BG 5/2） 等相近色。", "trap": "同色相相鄰明度階的辨識。", "src": "科目二指引 1.2", "fam": "find", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false}, {"id": "L12-3010", "codes": ["L12101", "L12102"], "diff": "中", "level": "應用", "type": "seq", "ans": ["15", "07", "35"], "stem": "左端為票號 36，右端為票號 21。請從色票卡上找出三張，依序補成由暗到亮的等色差色階，填入三個票號。【全對全錯】", "explain": "兩端只有明度不同（3→7），中間應為明度 4、5、6：15（5BG 4/4）、07（5BG 5/4）、35（5BG 6/4）。", "trap": "卡上的 09（10G 5/4） 色相偏移、30（5BG 5/2） 彩度降低、04（5BG 5.5/4） 明度不等距，分別對應三種錯誤。", "src": "簡章能力指標：調製兩色之間的等色差色階", "fam": "grad", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false}, {"id": "L12-3011", "codes": ["L12101", "L12102"], "diff": "中", "level": "應用", "type": "seq", "ans": ["03", "25", "14"], "stem": "左端為票號 31，右端為票號 01。請找出三張，依序補成由暗到亮的等色差色階。【全對全錯】", "explain": "中間階為明度 4、5、6、彩度 4：03（5PB 4/4）、25（5PB 5/4）、14（5PB 6/4）。", "trap": "卡上 5PB 明度 5 有多種彩度（/2、/6、/8、/10），選錯代表忽略了彩度要保持一致。", "src": "簡章能力指標", "fam": "grad", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false}, {"id": "L12-3012", "codes": ["L12101", "L12102"], "diff": "中", "level": "應用", "type": "seq", "ans": ["54", "46", "10"], "stem": "左端為票號 26，右端為票號 52。請找出三張，依序補成由灰到鮮豔的等色差色階。【全對全錯】", "explain": "兩端只有彩度不同（2→10），中間應為彩度 4、6、8：54（5R 5/4）、46（5R 5/6）、10（5R 5/8）。", "trap": "卡上的 08（5R 6/6）、17（5R 3/6） 彩度對但明度不同，是誘答。", "src": "簡章能力指標", "fam": "grad", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false}, {"id": "L12-3013", "codes": ["L12201", "L12101"], "diff": "難", "level": "分析", "type": "code", "ans": "2413", "stem": "四組配色：P1＝20、05、47；P2＝12、48、50；P3＝40、57、32；P4＝40、44、18。請依 P1～P4 順序填入配色法代號：1 鄰近色配色法、2 色調差配色法、3 色相差配色法、4 無彩配有彩。例如 1234。【全對全錯】", "explain": "P1 同色相、不同色調 → 2。P2 以無彩色為主、搭配小面積黃 → 4。P3 色相相鄰、色調相近 → 1。P4 同色調（明度 8、彩度 4）、色相差大 → 3。", "trap": "P1 與 P3 都看起來協調，關鍵在色相「相同」還是「相鄰」。", "src": "科目二指引 2.3；李文淵簡報 Hue-Tone 配色原則", "fam": "L12-3013", "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false}, {"id": "L12-3014", "codes": ["L12201", "L12102"], "diff": "難", "level": "應用", "type": "set", "ans": ["44", "18", "22"], "stem": "主色為票號 40。要用「色相差配色法」（同色調、不同色相）搭配，請從 44、18、20、05、57、22 中選出所有合適的票號，順序不拘。【全對全錯】", "explain": "同色調即明度與彩度都與主色相同（8/4）、色相不同：44（5PB 8/4）、18（5RP 8/4）、22（5G 8/4）。20（5Y 9/2）、05（5Y 7/6） 同色相，屬色調差；57（10YR 7/4） 明度不同。", "trap": "考 tonal 的條件是「色調一致」，而不是「看起來不同色」。", "src": "科目二指引 2.3（第 2-34 頁）", "fam": "L12-3014", "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false}, {"id": "L12-3015", "codes": ["L12201", "L12102"], "diff": "中", "level": "應用", "type": "set", "ans": ["42", "39", "53"], "stem": "主色為票號 38。要用「色調差配色法」（同色相、不同色調）搭配，請從 42、39、53、08、57、05 中選出所有合適的票號，順序不拘。【全對全錯】", "explain": "同色相 5YR 的三張：42（5YR 4/6）、39（5YR 8/4）、53（5YR 7/8）。其餘三張色相不同。", "trap": "57（10YR 7/4） 和 08（5R 6/6） 色相與主色相鄰，看起來很像，屬於鄰近色配色法。", "src": "科目二指引 2.3（第 2-33 頁）", "fam": "L12-3015", "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false}, {"id": "L12-3016", "codes": ["L12201", "L12101"], "diff": "中", "level": "理解", "type": "set", "ans": ["12", "16", "48"], "stem": "依李文淵簡報，CIELAB 彩度 C* ≤ 5 才算無彩色。請從 12、16、20、23、48、30 中選出所有可當作「無彩配有彩」中無彩色的票號。【全對全錯】", "explain": "無彩色只有 12（N 9）、16（N 5）、48（N 3）。孟塞爾彩度 2 的顏色，換算成 CIELAB 的 C* 約在 7–17（黃色最高），都超過 5，屬於低彩度的有彩色。", "trap": "低彩度不等於無彩色，是配色實務的常見誤解。", "src": "李文淵簡報（無彩配有彩）；科目二指引 2.3", "fam": "L12-3016", "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false}, {"id": "L12-3017", "codes": ["L12201", "L12102"], "diff": "難", "level": "應用", "type": "mc", "stem": "運動飲料包裝以票號 19 為大面積底色、票號 11 為標誌點綴色。依孟塞爾「色彩強度與面積成反比」原則，底色與標誌色的面積比約應為？", "opts": ["1：5", "12：5", "3：5", "5：1"], "explain": "強度＝明度×彩度：底色 3×4＝12，標誌色 5×12＝60。A₁/A₂＝V₂C₂/V₁C₁＝60/12＝5，弱色面積約為強色的 5 倍。", "trap": "1：5 把反比做成正比；12：5、3：5 只比較了單一屬性。", "src": "科目二指引 2.2（第 2-21 頁）", "fam": "area", "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L12-3018", "codes": ["L12201", "L12102"], "diff": "難", "level": "應用", "type": "mc", "stem": "一張海報以票號 34 為大面積背景，票號 53 為重點色。依孟塞爾面積平衡原則，背景與重點色的面積比約應為？", "opts": ["約 1：4.7", "約 4.7：1", "約 2：1", "約 7：3"], "explain": "背景強度 3×4＝12，重點色 7×8＝56。面積比＝56/12≈4.7，背景面積約為重點色的 4.7 倍。", "trap": "與上一題同概念、不同數字，用來確認不是背答案。", "src": "科目二指引 2.2", "fam": "area", "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L12-3019", "codes": ["L12102"], "diff": "易", "level": "理解", "type": "mc", "stem": "NCS 標記 S 1060-R20B，下列解讀何者正確？", "opts": ["含黑度 10%、彩度 60%、含白度 30%；色相為 20% 紅、80% 藍", "含黑度 60%、彩度 10%；色相為 80% 紅、20% 藍", "含白度 10%、彩度 60%；色相為 20% 紅、80% 藍", "含黑度 10%、彩度 60%、含白度 30%；色相為 80% 紅、20% 藍"], "explain": "前兩碼為含黑度 10，後兩碼為彩度 60，含白度＝100−10−60＝30。R20B 表示由紅往藍走 20%，即 80% 紅、20% 藍，是帶點紫的紅。", "trap": "R20B 的百分比指向後面的主色；黑度與彩度位置也常讀反。", "src": "科目二指引 1.2（第 2-10～2-11 頁）", "fam": "ncs", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L12-3020", "codes": ["L12102", "L13103"], "diff": "中", "level": "應用", "type": "mc", "stem": "某包裝標準色為 CIELAB (65, −25, 25)。下列何者正確？", "opts": ["C* ≈ 35.4，h＝45°，屬橙色", "C*＝50，h＝135°，屬黃綠色", "C* ≈ 35.4，h＝135°，屬黃綠色", "C* ≈ 35.4，h＝225°，屬青藍色"], "explain": "C*＝√(25²+25²)≈35.4。−a* 偏綠、+b* 偏黃，位於第二象限，h＝180°−45°＝135°。", "trap": "C*＝50 是把 |a*|、|b*| 相加；45° 是忘了判斷象限。", "src": "科目二指引 1.2（第 2-12～2-13 頁）", "fam": "lch", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L12-3021", "codes": ["L12201"], "diff": "易", "level": "知識", "type": "mc", "stem": "依官方參考指引，產品外觀色彩設計的思考流程分為三階段，正確順序為？", "opts": ["設定分色區域 → 解構與建構設計目標 → 檢視整體造形", "解構設計目標 → 設定分色區域 → 檢視整體造形", "檢視整體造形 → 設定分色區域 → 解構設計目標", "選定主色 → 選定輔色 → 設定分色區域"], "explain": "先設定分色區域（通常不超過 3 色），再把設計目標拆成關鍵字、對應三屬性選主色與輔色，最後搭配光澤、材質整體檢視；後兩階段會反覆來回。", "trap": "「先選主色」是直覺做法，但指引強調要先決定分色區域。", "src": "科目二指引 2.1（第 2-16～2-17 頁）", "fam": "planstep", "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L12-3022", "codes": ["L12201", "L11205"], "diff": "中", "level": "應用", "type": "mc", "stem": "一台有五個外觀組件的吹風機要做色彩計畫，設計目標是「專業、可靠」。下列做法何者最符合指引？", "opts": ["五個組件各用一色，以強化差異化", "外觀控制在 3 色以內，先把「專業、可靠」對應到低彩度、中低明度等屬性選主色，再以配色法選輔色", "依今年流行色決定主色，其餘由工廠配色", "先做 3D 彩現，以彩現圖上的顏色作為量產標準色"], "explain": "產品外觀以不超過 3 色為原則；色彩設計要把目標關鍵字轉成色彩三屬性的選擇，而不是依個人或流行偏好。3D 彩現受光影材質影響，不能當標準色。", "trap": "「差異化」是色彩計畫特性之一，但不是「每個組件都不同色」。", "src": "科目二指引 2.1（第 2-16～2-17 頁）", "fam": "L12-3022", "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-3001", "codes": ["L13102"], "diff": "易", "level": "知識", "stem": "下列光度量與單位的對應，何者正確？", "opts": ["照度：燭光（cd）；亮度：流明（lm）", "光通量：勒克斯（lx）；光強度：cd/m²", "照度：勒克斯（lx）；亮度：cd/m²（nit）", "光強度：流明（lm）；照度：瓦特（W）"], "explain": "光通量 lm、光強度 cd（lm/sr）、照度 lx（lm/m²）、亮度 cd/m²（nit）。", "trap": "四個光度量的單位彼此錯置。", "src": "科目三指引 1.1（第 2-5 頁）", "fam": "flux", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-3002", "codes": ["L13101"], "diff": "易", "level": "知識", "stem": "依光譜功率分布的型態，雷射光源屬於哪一種？", "opts": ["連續光譜", "線狀光譜", "帶狀與連續的組合光譜", "等能光譜"], "explain": "雷射只在一個或少數幾個波長發出狹窄譜線；鎢絲燈為連續光譜；螢光燈、白光 LED 為組合光譜。", "trap": "與官方例題相同概念，換成考雷射。", "src": "科目三指引 1.2（第 2-8、2-11～2-12 頁）", "fam": "L13-3002", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-3003", "codes": ["L13103"], "diff": "易", "level": "理解", "stem": "CIE 1931（2°）與 CIE 1964（10°）標準觀察者，下列敘述何者正確？", "opts": ["10° 適用於顯示器影像，2° 適用於大面積塗料", "兩者只差在使用年份，數據相同", "10° 觀察者的 Y 值不能代表亮度", "2° 適用於影像等小視角，10° 適用於油漆、照明等大面積色樣"], "explain": "2° 觀察者依小視角色刺激建立，10° 依大視角建立；以 10° 計算的刺激值記為 X₁₀Y₁₀Z₁₀。", "trap": "適用情境對調。", "src": "科目三指引 1.3（第 2-16～2-17 頁）", "fam": "L13-3003", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-3004", "codes": ["L13103", "L13102"], "diff": "中", "level": "理解", "stem": "A、B 兩色光以加法混合。下列關於混合光的敘述何者正確？", "opts": ["混合光的 (x, y) 一定落在 A、B 兩點的連線上，亮度 Y 為兩者相加", "混合光的 (x, y) 是兩點的簡單平均，與亮度無關", "混合光的 Y 取兩者中較大的值", "混合光的 (x, y) 可能落在 A、B 連線外"], "explain": "依格拉斯曼定律，兩色光混合後的色度點落在兩點連線上，偏向光量較多的一方；亮度具可加性。三色光混合則落在三點圍成的三角形內。", "trap": "簡單平均忽略了兩光的光量比例。", "src": "科目三指引 1.4（第 2-20 頁）", "fam": "L13-3004", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-3005", "codes": ["L13205"], "diff": "易", "level": "理解", "stem": "四色印刷設定「總墨量上限（TAC）」約 300%，主要目的是什麼？", "opts": ["避免油墨疊印過厚造成不易乾燥、背印或變形", "增加 CMY 三色的用量以擴大色域", "讓黑色看起來比較淡", "讓 RGB 可以不經轉換直接輸出"], "explain": "四色疊印理論上限 400%，墨量過多會乾燥不良、變形。超過上限時優先保留 K、等比例降低 CMY，這也是底色去除（UCR）的由來。", "trap": "TAC 是限制墨量，而不是增加。", "src": "科目三指引 2.3（第 2-47 頁）", "fam": "L13-3005", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-3006", "codes": ["L13203", "L13102"], "diff": "中", "level": "理解", "stem": "影片壓縮常先把 RGB 轉成 YCbCr，再降低 Cb、Cr 的解析度。這樣做的依據是？", "opts": ["人眼對色差訊號的解析力比亮度高", "人眼對亮度細節的解析力較高，對色差訊號的解析力較低", "YCbCr 是裝置無關色空間", "Cb、Cr 代表紅綠藍三原色"], "explain": "Y 接近明度訊號，Cb、Cr 是藍黃與紅綠的色差訊號。人眼對色差的空間解析力較低，所以降低色差通道解析度，畫面差異不明顯，卻能大幅壓縮資料量。", "trap": "與可視度題組呼應：細節辨識主要靠明度。", "src": "科目三指引 2.3（第 2-43 頁）", "fam": "L13-3006", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-3007", "codes": ["L13204", "L13202"], "diff": "中", "level": "應用", "stem": "光圈不變，快門由 1/60 秒改為 1/125 秒（約少一半曝光量）。要讓影像亮度維持不變，ISO 應如何調整？", "opts": ["由 ISO 100 降低到約 ISO 50", "ISO 不需調整", "由 ISO 100 提高到約 ISO 200", "由 ISO 100 提高到約 ISO 400"], "explain": "曝光時間減半，Tv 級數加 1，曝光量少一級；把感光度提高一倍（Sv 加 1）即可補償。", "trap": "APEX 每一級代表兩倍，提高到 ISO 400 會多補一級。", "src": "科目三指引 2.3（第 2-44 頁）", "fam": "L13-3007", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-3008", "codes": ["L13104"], "diff": "易", "level": "應用", "stem": "同一款手機殼有亮面版與霧面版，品管要客觀比較兩者的「光澤」差異，應使用哪一種儀器與單位？", "opts": ["分光光度儀，以 ΔE*ab 表示", "濃度計，以反射濃度 D 表示", "色度計，以 xy 色度座標表示", "光澤計，以 GU（光澤單位）表示"], "explain": "光澤計量測鏡面反射方向的光強度，以高光澤黑玻璃為 100 GU 的相對值。色差、濃度、色度座標描述的都是顏色，不是光澤。", "trap": "", "src": "科目三指引 2.1（第 2-33 頁）", "fam": "L13-3008", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-3009", "codes": ["L13206"], "diff": "易", "level": "知識", "stem": "紡織品的「色牢度」主要是在評估什麼？", "opts": ["布料的光澤程度", "染料的著色力", "布料的演色性", "染色經水洗、摩擦、日曬等處理後保持原色的能力"], "explain": "色牢度（color fastness）是紡織業檢測染色品在各種加工與使用後色彩維持的程度。", "trap": "著色力、遮蓋力、色牢度是色料的三種特性，容易混淆。", "src": "科目一指引 1.4（第 2-15 頁）", "fam": "L13-3009", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-3010", "codes": ["L13307", "L13202", "L13105"], "diff": "難", "level": "分析", "stem": "客戶依 5 cm 小色票選定牆面色，漆滿整面牆後卻覺得「太鮮、太亮」，但量測牆面與色票的 ΔE 很小。下列解釋何者最恰當？", "opts": ["色外貌會隨面積、背景與觀看條件改變；ΔE 只比較色度值，色外貌模式（如 CIECAM02）才把這些條件納入", "量測儀器故障，ΔE 應該很大", "牆面一定發生了條件等色", "只要 ΔE 小，任何條件下看起來都一定相同"], "explain": "同一色度值，大面積時通常看起來更亮、更鮮豔（面積效應）。CIELAB 色差不處理面積、背景、適應等條件，所以要用色外貌模式描述，實務上也應以大尺寸色板試色。", "trap": "「數值相同＝看起來相同」是色彩管理最常見的誤解。", "src": "吳瑞卿簡報（CIECAM02 考慮因素）；科目二指引 2.1 注意事項", "fam": "L13-3010", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-3011", "codes": ["L13306", "L13203"], "diff": "中", "level": "理解", "stem": "比較顯示規格 sRGB（Rec.709）、DCI-P3、Rec.2020 的色域大小，下列何者正確？", "opts": ["sRGB ＞ DCI-P3 ＞ Rec.2020", "Rec.2020 ＞ DCI-P3 ＞ sRGB（Rec.709）", "DCI-P3 ＞ Rec.2020 ＞ sRGB", "三者色域相同，只有白點不同"], "explain": "越新的規格色域越廣：Rec.2020（UHDTV）最大，DCI-P3 次之，sRGB 與 Rec.709 三原色相同、色域最小。", "trap": "考規格名稱與色域大小的對應。", "src": "科目三指引 2.3（第 2-42～2-43 頁）", "fam": "L13-3011", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-3012", "codes": ["L13301", "L13304", "L13302"], "diff": "難", "level": "分析", "stem": "設計部門有 10 台螢幕，同一張圖在每台上顏色都不同。要讓顏色盡量一致，下列流程何者最合理？", "opts": ["把每台螢幕的 RGB 滑桿調成相同數值", "所有螢幕套用同一個廠商預設描述檔即可", "用螢幕校色器把每台校準到相同目標（如 D65、120 cd/m²、γ2.2），量測產生各自的描述檔，並由作業系統套用", "用分光光度儀搭配白板校正量測紙張，再套用到螢幕"], "explain": "螢幕是裝置相關色，同樣的設定值在不同螢幕上不會一樣。要先校準到相同目標，再分別做特性描述產生各自的描述檔（3C 的前兩步）。量測螢幕要用測光源色的儀器。", "trap": "「同設定值」與「同描述檔」都忽略了每台裝置的個體差異。", "src": "徐明景簡報（3C）；科目三指引 2.1", "fam": "L13-3012", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-3013", "codes": ["L13101", "L13103"], "diff": "中", "level": "理解", "stem": "兩盞 LED 燈都標示相關色溫 4000 K，但一盞明顯偏綠、一盞偏洋紅。下列解釋何者正確？", "opts": ["相關色溫只是一維資訊；兩燈在 uv 色度圖上偏離黑體軌跡的方向不同，需搭配 Duv 描述", "兩燈的色溫其實不同，標示錯誤", "偏色是演色性不同造成，與色度座標無關", "相關色溫相同，色光就一定相同"], "explain": "色彩是二維色度資訊，CCT 只取最接近的黑體色溫。同一條等色溫線上的光可能偏綠或偏洋紅，照明業以 Duv 表示偏離黑體軌跡的程度。", "trap": "CCT 相同不代表光色相同，是照明規格判讀的重點。", "src": "科目三指引 1.2（第 2-10～2-11 頁）", "fam": "cct", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-4001", "codes": ["L11101", "L11301"], "diff": "中", "level": "應用", "stem": "某銀行把品牌色由紅改為深藍，希望傳達「穩健、可信賴」。這主要運用了色彩的哪些功能？", "opts": ["物體辨識功能", "象徵性與情緒影響功能", "指示性功能", "美感功能以外的任何功能都無關"], "explain": "色彩在特定文化中累積的象徵意義（藍＝理性、科學、可靠），以及對情緒的影響，是品牌用色的主要依據。", "trap": "指示性是用來區分類別或標示數值；這裡要傳達的是意義與感受。", "src": "科目一指引 1.1、3.1（第 2-2、2-43 頁）", "fam": "L11-4001", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-4002", "codes": ["L11101", "L11302", "L11205"], "diff": "難", "level": "分析", "stem": "醫院要重新規劃院內指標系統。下列哪一個色彩規劃方向，最能同時兼顧色彩的「指示性功能」與實際可用性？", "opts": ["所有指標使用同一個品牌色，視覺最統一", "每個區域使用多種鮮豔顏色，增加辨識趣味", "以色相區分區域即可，不需考慮明度差", "每個區域指定一個主色作為類別編碼，並確保文字與底色有足夠明度差，同時搭配編號與圖示"], "explain": "色彩編碼要讓類別清楚可辨（指示性），也要兼顧可視度（明度差）與通用設計（不只靠顏色）。統一單色無法區分區域；色彩過多會降低辨識效率。", "trap": "", "src": "科目一指引 1.1、3.2；謝翠如簡報（校園指標專案）", "fam": "L11-4002", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-4003", "codes": ["L11103", "L11104", "L11301"], "diff": "難", "level": "分析", "stem": "服飾店試衣間使用 2700 K、Ra 80 的暖光，顧客常抱怨「在店裡很好看，回家看顏色不一樣」。下列改善方式何者最合理？", "opts": ["把燈光調得更暗，讓顏色差異不明顯", "改用更低色溫的燈，讓衣服看起來更溫暖", "試衣間改用約 4000–5000 K、Ra ≥ 90 的光源，並在出口附近設置接近日光的對照光源", "只要提高照度就能解決"], "explain": "低色溫加上演色性不足，物體色會偏黃且失真；顧客回家在不同光源下看到的顏色自然不同（加上色彩恆常性也不完全）。提高演色性、使用接近日常的色溫，並提供對照光源最合理。", "trap": "照度與色溫、演色性是不同的指標。", "src": "科目一指引 1.3、1.4、3.1", "fam": "L11-4003", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-4004", "codes": ["L11104", "L11103", "L11106"], "diff": "難", "level": "分析", "stem": "舞台上一件白色戲服，同時被一盞紅色投射燈與一盞綠色投射燈照亮的區域，看起來最可能是什麼顏色？若改成紅色戲服在同樣的照明下呢？", "opts": ["白戲服看起來偏黃；紅戲服也看起來偏黃", "白戲服看起來偏黃；紅戲服看起來接近紅（只反射到紅光）", "白戲服看起來偏洋紅；紅戲服看起來黑", "兩者都維持原本的顏色"], "explain": "紅光與綠光投射在同一位置是加法混色，白色表面反射兩者，看起來偏黃。紅色物體主要只反射紅光、吸收綠光，所以看起來是紅色（亮度略低）。", "trap": "要同時運用加法混色與「物體色＝光源光譜 × 物體反射」兩個概念。", "src": "科目一指引 1.4、1.6", "fam": "L11-4004", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-4005", "codes": ["L11105", "L12102", "L11205"], "diff": "難", "level": "分析", "stem": "室內設計公司要和歐洲建材商溝通牆面色彩，對方使用 NCS，設計師手邊是孟塞爾色票。下列做法何者最恰當？", "opts": ["以實體色樣量測 CIELAB 值作為共同基準，再對應到雙方系統的標記，最後以實體色樣確認", "直接把孟塞爾標記的數字換成 NCS 的數字寫法", "兩個體系的色相環都是五主色，可以直接對照", "只要用色名溝通即可"], "explain": "孟塞爾（明度、彩度）與 NCS（含黑度、含白度、彩度；四主色）建構原理不同，無法用數字直接換算。以裝置無關的 CIELAB 為共同基準，再以實體色樣確認最可靠。", "trap": "NCS 依對立色理論只有四個主色。", "src": "科目一指引 1.5；科目二指引 1.2", "fam": "L11-4005", "type": "mc", "subj": "L11", "dom": "D2", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-4006", "codes": ["L11202"], "diff": "易", "level": "理解", "stem": "CIELAB 的明度 L* 不直接使用光線強度比例 Y/Yn，而是取其立方根再換算。主要原因是？", "opts": ["立方根比較容易用計算機計算", "為了讓黑色的 L* 等於 100", "為了配合印刷油墨的濃度", "人感覺到的明度與物理光強度呈非線性關係，需要以心理物理學的方法對應"], "explain": "光強度加倍，明度感覺並不會加倍。心理物理學把物理刺激量與主觀感覺對應起來，L* 公式就是這種非線性對應的結果。", "trap": "", "src": "科目一指引 2.2（第 2-28 頁）", "fam": "L11-4006", "type": "mc", "subj": "L11", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-4007", "codes": ["L11202", "L11206", "L13105"], "diff": "難", "level": "分析", "stem": "印刷廠與客戶約定「樣品與標準的 ΔE*ab 不得超過 2」。某批產品量得 ΔE*ab ＝ 1.8，客戶目視卻認為明顯偏色。下列判斷何者最合理？", "opts": ["數值合格就代表一定沒問題，客戶看錯了", "應把允差改成 ΔE*ab ≤ 10，避免爭議", "CIELAB 不是完全均勻的色空間，色差的感覺依色區與觀看條件不同；應在標準光源下目視確認，並考慮改用 CIEDE2000 等修正公式訂規格", "ΔE*ab 只計算明度差，所以看不出彩度差"], "explain": "ΔE*ab 是把感覺轉成數字的近似工具，在某些色區與條件下與目視不一致。規格要搭配目視確認與更貼近感覺的色差公式。", "trap": "ΔE*ab 包含明度、紅綠、黃藍三軸的差異。", "src": "科目一指引 2.2；科目二指引 2.1；科目三指引 2.2", "fam": "L11-4007", "type": "mc", "subj": "L11", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-4008", "codes": ["L11203", "L11207"], "diff": "中", "level": "理解", "stem": "一張照片從數位相機拍攝、在螢幕上編修、再由噴墨印表機輸出。關於這個色彩複製流程，下列敘述何者正確？", "opts": ["相機、螢幕、印表機都使用加法混色，所以顏色會完全相同", "只要螢幕亮度夠高，印出來就會一樣", "每個環節的成像原理與色域不同，原稿與最終複製物之間的差異需要用色彩管理控制", "色彩複製只與印表機的墨水有關"], "explain": "相機以感光元件擷取、螢幕以 RGB 自發光（加法）、噴墨以 CMYK 網點（減法）呈現，色域與原理都不同，所以要靠色彩管理維持一致。", "trap": "", "src": "科目一指引 2.3、2.7", "fam": "L11-4008", "type": "mc", "subj": "L11", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-4009", "codes": ["L11204"], "diff": "易", "level": "理解", "stem": "影像軟體的選色介面常用「色相環＋彩度／明度方塊」呈現。這樣設計的主要原因是？", "opts": ["色彩屬性是三維的，介面要把三個屬性轉成可在二維畫面上操作的形式", "螢幕只能顯示二維的顏色", "色相環是 CMYK 印刷的標準", "這樣可以讓顏色自動符合印刷色域"], "explain": "色彩有三個屬性，選色介面多半以色相為主要選擇維度，再搭配彩度與明度調整。", "trap": "", "src": "科目一指引 2.4（第 2-31 頁）", "fam": "L11-4009", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-4010", "codes": ["L11203", "L11206"], "diff": "中", "level": "理解", "stem": "同一份商品照片要用在電商網頁與印刷型錄。下列對「好的色彩複製」的理解何者正確？", "opts": ["只要兩個媒介的 RGB 數值相同就是好的複製", "可用色差做客觀評估，但也要依用途、觀看條件與客戶需求調整主觀評估標準", "只要印刷品比螢幕鮮豔就是好的複製", "好的色彩複製與用途無關"], "explain": "色彩複製品質可以客觀（色差）或主觀（用途、偏好、需求）衡量，兩者常同時使用。", "trap": "RGB 數值相同不代表兩個媒介呈現的顏色相同。", "src": "科目一指引 2.3（第 2-30 頁）", "fam": "L11-4010", "type": "mc", "subj": "L11", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-4011", "codes": ["L11207"], "diff": "易", "level": "理解", "stem": "單晶片 DLP 投影機只有一顆 DMD 晶片，它如何呈現全彩影像？", "opts": ["以紅綠藍子畫素並置混色", "以青、洋紅、黃三色濾鏡疊合的減法混色", "晶片本身會發出全彩光", "光源經色輪依序產生紅、綠、藍光，微反射鏡快速控制各色的時間，以時序混色在視覺上合成"], "explain": "單晶片 DLP 以色輪輪流投出 RGB，DMD 微鏡偏轉控制每個畫素各色的出光時間，眼睛的時間解析力不足而把它們混合。", "trap": "並置混色是 LCD／OLED 子畫素的機制。", "src": "科目一指引 2.7（第 2-39 頁）", "fam": "dlp", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-4012", "codes": ["L11401"], "diff": "易", "level": "理解", "stem": "客戶說：「我要同一個藍，但淺一點、柔和一點。」用 PCCS 的概念來看，設計師要調整的是什麼？", "opts": ["色相，改成偏綠的藍", "只調整色相與明度，彩度不變", "改用另一個色彩體系重新選色", "色調（明度與彩度的組合），色相維持不變"], "explain": "PCCS 以「色相＋色調」描述色彩。「淺、柔和」是色調形容詞（例如 lt、sf），同時牽涉明度與彩度；「同一個藍」表示色相不變。", "trap": "口語中的淺、深、柔、鮮，多半是色調而不是色相的變化。", "src": "科目一指引 4.1；科目二指引 1.1", "fam": "pccs", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-4013", "codes": ["L11401", "L11402", "L11205"], "diff": "難", "level": "分析", "stem": "兒童益智玩具品牌希望包裝「活潑、繽紛，但不雜亂」。下列哪一個配色策略最符合色彩秩序的原則？", "opts": ["使用同一明亮色調（如 PCCS b 或 v）中多個不同色相，形成色相差配色", "每個元素各自挑選不同色調、不同色相的鮮豔色", "全部使用灰色調，再以一個鮮色點綴", "只用同一色相的不同明度"], "explain": "指引認為美感來自潛藏的秩序：固定一個屬性（色調）、只變化另一個屬性（色相），可以同時得到繽紛與統一。", "trap": "色相與色調同時大幅變化容易雜亂；同色相配色無法達到繽紛。", "src": "科目一指引 4.1、4.2；李文淵簡報", "fam": "L11-4013", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-4014", "codes": ["L11402", "L11303", "L12201"], "diff": "難", "level": "分析", "stem": "運動品牌主視覺用紅色字放在綠色背景上（互補色、彩度都高），在大型看板上顯得刺眼且邊緣閃爍。下列調整何者最能保留「強烈對比」又改善問題？", "opts": ["把紅字改成綠色背景的同色相", "保留互補色相，但拉開兩者的明度差，並在字的外框加白色或黑色描邊", "把兩色的彩度都提高", "改用鄰近色配色法"], "explain": "互補色並置會產生強烈的色相對比；明度相近時又會產生色滲與閃爍。拉開明度差、以中性色描邊，可保留色相對比，同時改善可讀性。", "trap": "改成鄰近色或同色相會失去品牌要的強烈對比。", "src": "科目一指引 3.3、4.2；科目二指引 2.3", "fam": "L11-4014", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-4015", "codes": ["L11404"], "diff": "易", "level": "理解", "stem": "選擇色相、明度一致，只有彩度不同的顏色互相搭配，通常會產生什麼效果？", "opts": ["強烈刺激、對比鮮明", "繽紛活潑", "緩和、淡雅、簡單，適合作為背景用色", "與單一顏色完全相同"], "explain": "以彩度為主的配色中，同色相、同明度、不同彩度的組合，視覺上緩和淡雅。", "trap": "", "src": "科目一指引 4.4（第 2-57 頁）", "fam": "L11-4015", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-4016", "codes": ["L11404", "L11301", "L11205"], "diff": "難", "level": "分析", "stem": "一家精品咖啡店要同時推出兩條產品線：給年輕上班族的「活力系列」與給熟客的「經典系列」。依以彩度為主的配色原則，下列規劃何者最合適？", "opts": ["兩系列都用高彩度，差別只在 logo 大小", "活力系列用低彩度、經典系列用高彩度", "活力系列採高彩度的同彩度組合，經典系列採中低彩度的同彩度組合，兩系列可共用部分色相以維持品牌一致", "兩系列各自隨機挑色，以強調差異化"], "explain": "高彩度同彩度組傳達活潑年輕，中低彩度組傳達穩重成熟；共用色相能在差異化之外維持品牌一致化。", "trap": "", "src": "科目一指引 4.4；科目二指引 2.1（色彩計畫四特性）", "fam": "L11-4016", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-4001", "codes": ["L13104", "L13207", "L13105"], "diff": "難", "level": "分析", "stem": "同一塊金屬漆樣品，A 廠用 45°/0° 儀器、B 廠用 d/8°（SPIN）儀器量測，兩邊的 L*a*b* 差很多，雙方都說自己的數據才對。下列處置何者最恰當？", "opts": ["以數值較接近標準的那一廠為準", "雙方先約定相同的量測幾何條件（含是否包含鏡面反射）與光源、觀察者，再比較數據；必要時輔以目視", "兩廠數據取平均即可", "換成光澤計量測就能得到正確的 L*a*b*"], "explain": "量測幾何會影響結果，高光澤或金屬漆尤其明顯。CIE 規範幾何條件，就是為了讓不同儀器能得到可比較的數據。光澤計只量光澤度，無法得到色度值。", "trap": "", "src": "科目三指引 2.1（第 2-33～2-36 頁）", "fam": "L13-4001", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-4002", "codes": ["L13105"], "diff": "易", "level": "理解", "stem": "CIELAB 色差公式中，ΔE*ab ≈ 1 通常被視為什麼？", "opts": ["約為人眼恰可察覺的色差", "兩色完全相同", "兩色差異極大", "明度差剛好等於 1"], "explain": "ΔE*ab ＝ 1 約為人眼恰可察覺的色差（實際依色區與條件而異）。", "trap": "", "src": "科目三指引 2.2（第 2-39 頁）；吳瑞卿簡報", "fam": "L13-4002", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-4003", "codes": ["L13201"], "diff": "易", "level": "知識", "stem": "色彩複製（color reproduction）的基本架構，下列描述何者正確？", "opts": ["只能從印刷品複製到印刷品", "複製物一定與原稿的光譜完全相同", "色彩複製只發生在數位設備之間", "原稿（場景或物體）經由照相、印刷、顯示等再現過程，產生複製物"], "explain": "原稿可以是場景或物體，經各種成像技術再現為複製物；目標通常是色彩感覺一致，而非光譜相同。", "trap": "", "src": "科目一指引 2.3；陳鴻興簡報（色彩再現之意義）", "fam": "L13-4003", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-4004", "codes": ["L13201", "L13203", "L13205"], "diff": "難", "level": "分析", "stem": "博物館要把一幅古畫數位典藏，並同時用於網站展示與高品質複製畫印刷。下列流程何者最合理？", "opts": ["直接用手機拍攝 JPEG，網站與印刷都用同一個檔案", "先轉成 CMYK 保存母檔，網站再從 CMYK 轉回來", "只要螢幕上看起來與原畫一樣即可，不需打樣", "在標準照明下拍攝並搭配色導表，以大色域工作空間保存母檔；網站版轉為 sRGB，印刷版依印刷條件的描述檔轉換並打樣確認"], "explain": "母檔應保留最多色彩資訊並有色彩參考；不同輸出媒介色域不同，要分別轉換。先轉成較小色域的 CMYK 會永久失去色彩資訊。", "trap": "", "src": "科目三指引 2.3；陳鴻興簡報；徐明景簡報", "fam": "L13-4004", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-4005", "codes": ["L13202"], "diff": "易", "level": "知識", "stem": "CIE 建議目視比較色差時的觀看條件，下列何者正確？", "opts": ["D65 光源、約 1000 lx、L*≈50 的中灰背景", "A 光源、約 100 lx、黑色背景", "任何光源都可以，只要夠亮", "D50 光源、白色背景、越亮越好"], "explain": "指引列出 CIE 建議：照度約 1000 lx 的 D65 光源、中灰背景（L*a*b* ≈ 50, 0, 0）、相鄰兩樣本、視角大於 4°。", "trap": "", "src": "科目三指引 2.2（第 2-40 頁）", "fam": "L13-4005", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-4006", "codes": ["L13206", "L13105"], "diff": "中", "level": "應用", "stem": "紡織業評估色差時，常把 CIEDE2000 的權重設為 (kL, kC, kH) ＝ (2, 1, 1)。這代表什麼？", "opts": ["提高明度差的權重為兩倍", "降低明度差在色差中的權重，因為布料紋理使明度差較不易被察覺", "只計算明度差", "完全不計算色相差"], "explain": "k 值越大，該分量在公式中被除得越多，權重越低。紡織品表面紋理使明度差較不敏感，因此 kL ＝ 2。", "trap": "k 值與權重是反向關係，最常被理解反。", "src": "科目三指引 2.2（第 2-40 頁）", "fam": "L13-4006", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-4007", "codes": ["L13207"], "diff": "易", "level": "理解", "stem": "同一個顏色做成高光澤與霧面兩種表面，在一般室內觀看時，下列敘述何者正確？", "opts": ["表面處理只影響手感，不影響顏色", "霧面一定比高光澤看起來更鮮豔", "表面處理不同會改變色彩外觀，例如高光澤表面在避開反光的角度通常看起來更深、更飽和", "只要色料相同，任何表面看起來都一樣"], "explain": "光澤影響鏡面反射與擴散反射的比例，進而改變色外貌，因此 CMF 設計要同時考慮色彩、材質與表面處理。", "trap": "", "src": "科目一指引 1.1、1.4；科目二指引 2.1", "fam": "L13-4007", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-4008", "codes": ["L13207", "L13104", "L13302"], "diff": "難", "level": "分析", "stem": "3C 外殼同一色號分別用塑膠射出（霧面）與金屬烤漆（高光澤）兩種製程，量產後並排總覺得不一樣。下列品管策略何者最恰當？", "opts": ["兩種材質都使用同一個 L*a*b* 標準值即可", "只要色料配方相同，量產一定一致", "依材質分別建立標準樣與允差，量測時明確規定幾何條件（如是否含鏡面反射），並在標準光源下並排目視確認", "改用螢幕截圖的 RGB 值作為兩廠共同標準"], "explain": "材質與表面處理不同，同樣色料也會有不同色外貌，量測值也受幾何條件影響。CMF 品管要為不同材質分別建立標準，並統一量測與觀看條件。", "trap": "", "src": "科目三指引 2.1；職能基準 T3c（CMF 領域）", "fam": "L13-4008", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-4009", "codes": ["L13301"], "diff": "易", "level": "知識", "stem": "色彩管理系統最核心的目標是什麼？", "opts": ["讓色彩在不同裝置與媒介間盡量維持一致，接近「所見即所得」", "讓所有螢幕都顯示最鮮豔的顏色", "讓 RGB 數值在所有裝置上都相同", "降低印刷成本"], "explain": "色彩管理希望色彩經過複製或生產後，仍能穩定呈現原本設定的樣子（WYSIWYG）。", "trap": "RGB 數值相同不等於顏色相同。", "src": "科目一指引 2.6（第 2-35 頁）；徐明景簡報", "fam": "L13-4009", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-4010", "codes": ["L13301", "L13303"], "diff": "中", "level": "理解", "stem": "徐明景老師以「翻譯」比喻色彩管理：法文要翻成日文，先翻成英文當中介。對應到色彩管理系統，下列何者正確？", "opts": ["CMYK 是中介語言，RGB 與 CIELAB 是兩端", "RGB 與 CMYK 是裝置相關的「語言」，CIELAB（PCS）是共同的中介，描述檔則是各語言的字典", "描述檔是中介語言，PCS 是字典", "不需要中介，RGB 可直接換成 CMYK"], "explain": "色彩管理透過描述檔把裝置訊號轉到裝置無關的 PCS（CIELAB），再轉到目標裝置，CIELAB 擔任中介的角色。", "trap": "", "src": "徐明景簡報（色彩對應的原理）", "fam": "L13-4010", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-4011", "codes": ["L13303", "L13305"], "diff": "中", "level": "理解", "stem": "色彩管理系統要完成一次 RGB 到 CMYK 的轉換，下列哪一組元件缺一不可？", "opts": ["只要目的描述檔", "只要色彩轉換引擎", "只要演色意圖", "來源描述檔、目的描述檔、色彩轉換引擎（CMM），並選定演色意圖"], "explain": "轉換需要前端描述檔（RGB → PCS）、後端描述檔（PCS → CMYK）、色彩引擎執行運算，再依演色意圖處理色域外的顏色。", "trap": "", "src": "科目一指引 2.6；徐明景簡報（Photoshop 實務應用）", "fam": "L13-4011", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-4012", "codes": ["L13304"], "diff": "易", "level": "知識", "stem": "螢幕校色常用的「校色器」，一般屬於哪一類量測儀器？", "opts": ["光澤計", "濃度計", "分光光度儀加白板", "色度計（以染料濾鏡分光，輕便，適合螢幕校正）"], "explain": "色度計以寬頻濾鏡感光，準確度不如光譜儀但輕便，適合螢幕色彩校正與色差比較。", "trap": "", "src": "科目三指引 2.1（第 2-32 頁）", "fam": "L13-4012", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-4013", "codes": ["L13304", "L13302"], "diff": "中", "level": "應用", "stem": "螢幕校準完成並產生描述檔後，三個月後色彩開始偏移。下列做法何者正確？", "opts": ["描述檔永久有效，不需處理", "定期重新校準與特性描述，因為顯示器會隨使用時間老化、漂移", "只要調整作業系統的亮度滑桿即可", "改用別人的描述檔"], "explain": "特性描述的前提是裝置維持在校準後的穩定狀態；裝置漂移後，舊描述檔就不再準確，需要定期重做。", "trap": "", "src": "徐明景簡報（3C、穩定環境）", "fam": "L13-4013", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-4014", "codes": ["L13305"], "diff": "易", "level": "理解", "stem": "在色彩管理系統中選擇演色意圖（rendering intent），主要應依據什麼來決定？", "opts": ["螢幕的品牌", "檔案大小", "影像內容與用途，例如自然影像、商業圖表或印刷打樣", "固定使用同一種意圖，結果都一樣"], "explain": "四種演色意圖處理色域外顏色的方式不同：感應式適合自然影像，飽和度式適合商業圖表，色度式適合重視色度準確的打樣。", "trap": "", "src": "科目一指引 2.6（第 2-36 頁）", "fam": "intent", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-4015", "codes": ["L13306"], "diff": "易", "level": "知識", "stem": "一般網頁瀏覽器與網站圖片的預設色彩空間是？", "opts": ["sRGB", "Adobe RGB", "ProPhoto RGB", "CMYK"], "explain": "網頁預設 sRGB；Adobe RGB 適合商業攝影與高品質印刷；CMYK 用於印刷。", "trap": "", "src": "科目二指引 2.4；徐明景簡報", "fam": "srgb", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-4016", "codes": ["L13306", "L13203", "L13305"], "diff": "難", "level": "分析", "stem": "品牌要同時在 HDR 廣色域電視廣告（Rec.2020 規格）、手機網頁（sRGB）與報紙（新聞紙印刷）呈現同一個鮮豔的品牌紅。下列策略何者最合理？", "opts": ["以 Rec.2020 的數值為準，直接套用到所有媒介", "以報紙能印出的顏色為準，其他媒介都刻意調暗", "每個媒介各自調整到看起來最鮮豔即可", "以裝置無關的 CIELAB 值與實體色樣定義品牌紅，再針對各媒介分別訂出最接近的再現值，接受部分媒介無法完全重現"], "explain": "三種媒介的色域差異很大，同一數值不可能在所有媒介都相同。以裝置無關的標準定義品牌色，再依各媒介的色域與演色意圖分別處理，是跨媒體色彩管理的做法。", "trap": "", "src": "科目三指引 2.3；徐明景簡報", "fam": "L13-4016", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-4017", "codes": ["L13307"], "diff": "易", "level": "知識", "stem": "CIECAM02 這類「色外貌模式」相較於 CIELAB，多考慮了哪些因素？", "opts": ["只考慮色料的成分", "觀看環境的背景、亮度適應、色適應等條件", "只考慮螢幕的解析度", "與 CIELAB 完全相同"], "explain": "色外貌模式把背景、環境光、適應狀態等觀看條件納入，用來預測同一刺激在不同條件下看起來的樣子。", "trap": "", "src": "吳瑞卿簡報（CIECAM02）", "fam": "L13-4017", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-4018", "codes": ["L13307", "L11301"], "diff": "中", "level": "理解", "stem": "同一張照片在昏暗的電影院大銀幕與明亮辦公室的手機上看，色彩感覺不同。下列哪一個概念最能說明為什麼需要「色外貌模式」？", "opts": ["色彩感覺會受觀看環境與適應狀態影響，相同的色度值在不同條件下看起來不同", "兩個裝置的 RGB 值不同", "手機一定比電影院的色域大", "只要 ΔE*ab 為 0，看起來就一定相同"], "explain": "色彩恆常性、亮度與色適應都會改變色外貌；CIELAB 未納入這些條件，因此需要色外貌模式。", "trap": "", "src": "科目一指引 3.1；吳瑞卿簡報", "fam": "L13-4018", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-4019", "codes": ["L13303", "L13302"], "diff": "中", "level": "應用", "stem": "在 Photoshop 中打開一張沒有嵌入描述檔的 RGB 照片。下列做法何者正確？", "opts": ["直接「轉換」為 CMYK，因為印刷一定要 CMYK", "不處理，因為沒有描述檔就代表色彩正確", "依影像來源判斷原本的色彩空間（如手機照片多為 sRGB），以「指定描述檔」標示，之後輸出時再「轉換」", "每個人隨意指定都可以，結果都一樣"], "explain": "沒有描述檔時，同樣的 RGB 數值意義不明，要先「指定」正確的來源描述檔來解讀數值；輸出到其他媒介時再「轉換」。", "trap": "「指定」是告訴系統數值代表什麼，「轉換」才會改變數值。", "src": "徐明景簡報（指定色彩描述檔）", "fam": "L13-4019", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-1001", "codes": ["L11104"], "diff": "易", "level": "理解", "stem": "在物體表面的光效應中，下列敘述何者正確？", "opts": ["鏡面反射時反射光的方向不遵守反射定律", "擴散反射會產生物體表面的光澤感", "漫射時反射光線以各種不同角度射出", "光滑表面較容易產生漫射效果"], "explain": "粗糙表面易產生漫射，反射光向各方向散出；光滑表面易產生鏡射，形成光澤。", "trap": "把鏡射與漫射的成因、效果對調。", "src": "科目一指引 1.4（第 2-14～2-15 頁）", "origin": "學生協助命題（115 審修）", "fam": "L11-1001", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "C"}, {"id": "L11-1002", "codes": ["L11103"], "diff": "易", "level": "理解", "stem": "某 LED 產品規格標示演色指數 Ra = 95，這代表什麼意義？", "opts": ["光源的色溫接近日光", "在此光源下物體呈現的顏色，非常接近在同色溫參考光源下的顏色", "光源的發光效率很高", "光源的亮度比一般燈具高 95%"], "explain": "Ra 比較待測光源與同色溫參考光源下標準色票的色差，100 為完全一致；Ra ≥ 95 適合對色、攝影等需要忠實呈現色彩的場合。", "trap": "演色性與色溫、發光效率、亮度都是不同指標。〔審修：原題兩個選項都可解為正確，已改寫誘答〕", "src": "科目一指引 1.4（第 2-14 頁）；科目三指引 1.5", "origin": "學生協助命題（115 審修）", "fam": "cri", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "B"}, {"id": "L11-1003", "codes": ["L11201"], "diff": "易", "level": "理解", "stem": "在數位影像系統中，色彩深度（color depth）與下列何者關係最密切？", "opts": ["每個像素用來記錄色彩的位元數", "光源的色域範圍大小", "物體的光譜反射特性", "畫面的動態對比範圍"], "explain": "色彩深度指記錄色彩階調所使用的位元數，位元數越多，可表現的階調越細緻。", "trap": "色域（範圍）與色彩深度（階數）常被混淆。", "src": "科目一指引 2.1（第 2-25～2-26 頁）", "origin": "學生協助命題（115 審修）", "fam": "L11-1003", "type": "mc", "subj": "L11", "dom": "D3", "diag": false, "ans": "A"}, {"id": "L13-1001", "codes": ["L13102", "L13101"], "diff": "中", "level": "應用", "stem": "某 LED 燈具標示：色溫 6500 K、Ra 92、功率 10 W、照度 1200 lx。下列哪一項資訊無法從這些規格直接得知？", "opts": ["光源的色溫特性", "光源的演色特性", "在標示條件下的照度", "光源的發光效率（lm/W）"], "explain": "發光效率＝光通量（lm）÷ 電功率（W）。規格只給照度（lx，與量測距離有關），沒有總光通量，無法算出 lm/W。", "trap": "照度與光通量單位不同，不能直接拿來除以功率。", "src": "科目三指引 1.1（第 2-4～2-5 頁）", "origin": "學生協助命題（115 審修）", "fam": "L13-1001", "type": "mc", "subj": "L13", "dom": "D1", "diag": false, "ans": "D"}, {"id": "L11-1005", "codes": ["L11102"], "diff": "易", "level": "知識", "stem": "視網膜上的感光細胞分為錐狀細胞與桿狀細胞。下列敘述何者錯誤？", "opts": ["錐狀細胞主要集中在中央小窩", "桿狀細胞數量遠多於錐狀細胞", "桿狀細胞無法分辨色彩", "錐狀細胞負責暗視覺"], "explain": "暗視覺由桿狀細胞負責；錐狀細胞在明亮環境下作用，負責色彩視覺。", "trap": "〔審修：原選項寫錐狀細胞「約 600 萬個」，官方資料有 600 萬、700 萬、800 萬三種說法，已改為不考精確數字〕", "src": "科目一指引 1.2", "origin": "學生協助命題（115 審修）", "fam": "rodcone", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "D"}, {"id": "L11-1006", "codes": ["L11102"], "diff": "易", "level": "理解", "stem": "某品管人員在色覺測試中無法正確辨識紅色與綠色。下列敘述何者最可能正確？", "opts": ["缺乏或異常的是 L 型（長波）或 M 型（中波）錐狀細胞", "缺乏 S 型（短波）錐狀細胞，導致藍黃混淆", "完全缺乏所有錐狀細胞", "視網膜受損，所有顏色都呈灰階"], "explain": "第 1、2 型色覺異常分別與 L、M 錐狀細胞有關，都會混淆紅綠；缺 S 是第 3 型；全色盲極罕見。", "trap": "可作為診斷卷第 1 題的平行題。", "src": "科目一指引 1.2（第 2-8 頁）", "origin": "學生協助命題（115 審修）", "fam": "cvd", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "A"}, {"id": "L11-1007", "codes": ["L11103"], "diff": "易", "level": "理解", "stem": "關於光的物理特性，下列敘述何者錯誤？", "opts": ["可見光的波長範圍約介於 380 nm 至 780 nm", "光源演色性越低，色彩呈現越接近自然日光", "色光的加法混色適用於螢幕、投影機等自發光裝置", "太陽光是熱效應光源，具有接近全光譜的特性"], "explain": "演色性越高才越接近參考光源（日光）下的色彩表現。", "trap": "把演色性的高低方向弄反。", "src": "科目一指引 1.3、1.4", "origin": "學生協助命題（115 審修）", "fam": "L11-1007", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "B"}, {"id": "L11-1009", "codes": ["L11303"], "diff": "易", "level": "理解", "stem": "凝視某個色相一段時間後轉看白色區域，出現的後像（殘像）會呈現什麼顏色？", "opts": ["與原色相相同的顏色", "原色相的高明度版本", "原色相的心理補色", "與原色相混合的灰色"], "explain": "繼時對比中，後像往心理補色方向出現，與對立色處理機制有關。", "trap": "", "src": "科目一指引 3.3（第 2-49～2-50 頁）", "origin": "學生協助命題（115 審修）", "fam": "after", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "C"}, {"id": "L11-1010", "codes": ["L11303"], "diff": "易", "level": "理解", "stem": "兩個中高彩度、明度相近的顏色相鄰時產生色滲。要減低色滲，下列何者最有效？", "opts": ["增加兩色的彩度", "擴大兩色的接觸面積", "在兩色之間加入黑色或其他中性色的邊線", "讓兩色的明度更接近"], "explain": "以中性色隔開，可降低同時對比與色滲效果。", "trap": "提高彩度、讓明度更接近，都會讓色滲更嚴重。", "src": "科目一指引 3.3（第 2-49 頁）", "origin": "學生協助命題（115 審修）", "fam": "bleed", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "C"}, {"id": "L11-1011", "codes": ["L11303"], "diff": "易", "level": "理解", "stem": "下列哪一種情況最容易產生色彩同化現象？", "opts": ["大面積的純色背景", "顏色被切割成極細小的條紋或圖案", "強烈的明度對比", "互補色的大面積並置"], "explain": "相鄰色面積非常細小時，色彩對比會被同化取代，鄰近色互相趨近。", "trap": "", "src": "科目一指引 3.3（第 2-51 頁）", "origin": "學生協助命題（115 審修）", "fam": "assim", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "B"}, {"id": "L11-1012", "codes": ["L11302"], "diff": "易", "level": "應用", "stem": "數位廣告看板要讓關鍵文字在複雜背景中保持清晰可讀，最應優先採用哪一項原則？", "opts": ["使用多種色相增加視覺趣味", "運用色彩同化提升協調性", "增加背景的色彩豐富度", "確保文字與背景有足夠的明度對比"], "explain": "提高可視度的關鍵是明暗對比，其次是字體尺寸與粗細；只有色相差、沒有明度差的配色可視度差。", "trap": "", "src": "科目一指引 3.2（第 2-45 頁）", "origin": "學生協助命題（115 審修）", "fam": "visib", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "D"}, {"id": "L11-1013", "codes": ["L11303"], "diff": "易", "level": "分析", "stem": "長時間注視某色彩後再看白色區域會產生後像。下列哪一個條件「不利於」產生後像？", "opts": ["眼球快速且頻繁地移動", "觀察目標有足夠大的面積", "眼球持續注視固定位置", "刺激物保持穩定的色彩強度"], "explain": "後像需要視網膜接受穩定、持續、面積足夠的刺激；眼球持續移動或面積太小就看不到。", "trap": "", "src": "科目一指引 3.3（第 2-50 頁）", "origin": "學生協助命題（115 審修）", "fam": "after", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "A"}, {"id": "L11-1014", "codes": ["L11303"], "diff": "易", "level": "分析", "stem": "關於色彩對比與色彩同化，下列敘述何者正確？", "opts": ["面積大小是決定產生對比或同化的主要因素之一", "同時對比與繼時對比的效果完全相同", "大面積的細紋理圖案容易產生色彩對比", "色彩同化只發生在無彩色之間"], "explain": "相鄰色面積夠大時偏向對比（差異被強化），面積極小時偏向同化（互相趨近）。", "trap": "", "src": "科目一指引 3.3", "origin": "學生協助命題（115 審修）", "fam": "assim", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "A"}, {"id": "L11-1016", "codes": ["L11205"], "diff": "易", "level": "知識", "stem": "色彩計畫的實務工作步驟，正確順序為何？", "opts": ["測試 → 提案 → 打樣 → 品管追蹤", "打樣 → 測試 → 提案 → 品管追蹤", "品管追蹤 → 提案 → 打樣 → 測試", "提案 → 打樣 → 測試 → 品管追蹤"], "explain": "提案階段包含趨勢調查、品牌與市場定位；打樣與測試反覆修正；最後與生產部門進行品管追蹤。", "trap": "", "src": "科目一指引 2.5（第 2-33 頁）；科目二指引 2.1", "origin": "學生協助命題（115 審修）", "fam": "planstep", "type": "mc", "subj": "L11", "dom": "D5", "diag": false, "ans": "D"}, {"id": "L11-1021", "codes": ["L11301"], "diff": "易", "level": "應用", "stem": "某語言只有黑、白、紅三個基本色名。依跨文化研究的色名發展順序，它接下來最可能發展出哪一個基本色名？", "opts": ["藍", "咖啡色", "黃或綠", "粉紅"], "explain": "跨文化研究發現基本色名的發展順序有共通性：黑白 → 紅 → 黃或綠 → 藍。咖啡色這類借代其他事物的名稱不算基本色名。", "trap": "", "src": "科目一指引 3.1（第 2-42～2-43 頁）", "origin": "學生協助命題（115 審修）", "fam": "L11-1021", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "C"}, {"id": "L11-1022", "codes": ["L11301"], "diff": "易", "level": "理解", "stem": "關於色彩命名的標準化，下列敘述何者錯誤？", "opts": ["ISCC-NBS 以「色調修飾語＋基本色名」形式命名", "所有文化的色彩命名系統都完全相同", "日本工業標準（JIS）訂有色彩名稱規範", "工商業發展成熟的語言，通常發展出較多色名"], "explain": "各文化的色名發展順序有共通性，但最終色名數量與內容不同。", "trap": "", "src": "科目一指引 3.1（第 2-42 頁）", "origin": "學生協助命題（115 審修）", "fam": "L11-1022", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "B"}, {"id": "L11-1023", "codes": ["L11205", "L12102"], "diff": "中", "level": "應用", "stem": "進行工業產品的色彩規格溝通時，下列哪一種做法最恰當？", "opts": ["只用口語化的色彩形容詞溝通", "提供實體標準色樣，並附上 CIELAB 或孟塞爾等裝置無關的色彩標記", "只提供 RGB 或 CMYK 數值", "只提供品牌自訂的色名"], "explain": "色彩計畫要以標準色樣與色彩標記作為生產依據；RGB、CMYK 是裝置相關色，口語與自訂色名缺乏精確性。", "trap": "〔審修：原答案「系統化的 RAL 或 DIC 色彩體系」有爭議，RAL、DIC 屬商業色票系統，Pantone 也同樣合理，已改寫〕", "src": "科目二指引 2.1（第 2-17 頁）；李文淵簡報（色彩系統分類）", "origin": "學生協助命題（115 審修）", "fam": "L11-1023", "type": "mc", "subj": "L11", "dom": "D5", "diag": false, "ans": "B"}, {"id": "L11-1024", "codes": ["L11301", "L11205"], "diff": "難", "level": "分析", "stem": "跨國企業要在不同語言地區推廣同一產品，關於產品色彩的命名與溝通策略，下列何者最適當？", "opts": ["直接翻譯原產地的色名即可", "只使用 RGB 數值描述", "以國際通用的色彩標記（如色票編號、CIELAB 值）作為內部標準，對外搭配在地化色名", "完全採用原產地的色名系統"], "explain": "色名受文化影響，聯想與數量都不同；內部規格要用不受語言影響的標記，對消費者則用在地文化能理解的色名。", "trap": "", "src": "科目一指引 3.1", "origin": "學生協助命題（115 審修）", "fam": "L11-1024", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "C"}, {"id": "L11-1025", "codes": ["L11205"], "diff": "易", "level": "知識", "stem": "關於色彩計畫的四大特性，下列何者錯誤？", "opts": ["系統化主要依靠設計師的直覺經驗", "科學化是依據客觀調查資料進行", "一致化是維持各階段色彩形象的統一", "差異化是突顯設計主體與競品的差異"], "explain": "系統化是指適當運用色彩體系來規劃與管理色彩，而不是依賴直覺。", "trap": "", "src": "科目二指引 2.1（第 2-15 頁）", "origin": "學生協助命題（115 審修）", "fam": "plan4", "type": "mc", "subj": "L11", "dom": "D5", "diag": false, "ans": "A"}, {"id": "L13-1029", "codes": ["L13102"], "diff": "易", "level": "知識", "stem": "關於光通量（luminous flux），下列敘述何者正確？", "opts": ["單位為燭光（cd）", "不需考慮人眼的視覺特性", "與輻射通量完全相同", "單位為流明（lm）"], "explain": "光通量是輻射通量經人眼光譜光視效率函數加權後的量，單位為流明。", "trap": "", "src": "科目三指引 1.1（第 2-4 頁）", "origin": "學生協助命題（115 審修）", "fam": "flux", "type": "mc", "subj": "L13", "dom": "D1", "diag": false, "ans": "D"}, {"id": "L13-1031", "codes": ["L13101"], "diff": "易", "level": "理解", "stem": "LED 光源標示相關色溫（CCT）6500 K，代表什麼？", "opts": ["LED 實際工作溫度為 6500 K", "LED 的使用壽命為 6500 小時", "其光色接近 6500 K 黑體輻射的顏色", "LED 的功率為 6500 瓦"], "explain": "相關色溫是在色度圖上最接近該光色的黑體溫度，與燈具實際溫度無關。", "trap": "", "src": "科目三指引 1.2（第 2-10 頁）", "origin": "學生協助命題（115 審修）", "fam": "cct", "type": "mc", "subj": "L13", "dom": "D1", "diag": false, "ans": "C"}, {"id": "L13-1032", "codes": ["L13102"], "diff": "易", "level": "理解", "stem": "在沒有其他光源干擾的理想情況下，點光源的照度與距離的關係為何？", "opts": ["照度與距離平方成反比", "照度與距離無關", "照度與距離平方成正比", "照度與距離成反比"], "explain": "照度與光源到量測面的距離平方成反比。", "trap": "部分講義誤植為「平方成正比」。", "src": "科目三指引 1.1（第 2-5 頁）", "origin": "學生協助命題（115 審修）", "fam": "illum", "type": "mc", "subj": "L13", "dom": "D1", "diag": false, "ans": "A"}, {"id": "L11-1033", "codes": ["L11103", "L13101"], "diff": "中", "level": "分析", "stem": "關於色溫與演色性的關係，下列敘述何者正確？", "opts": ["色溫越高，演色性必定越好", "演色性高的光源，色溫一定高於 5000 K", "高演色性的光源，色溫一定低於 3000 K", "色溫與演色性是兩個獨立的光源特性"], "explain": "色溫描述光色偏黃或偏藍，演色性描述光源呈現物體顏色的忠實程度，兩者分別指定。", "trap": "", "src": "科目一指引 1.3、1.4；科目三指引 1.5", "origin": "學生協助命題（115 審修）", "fam": "lightspec", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "D"}, {"id": "L11-1034", "codes": ["L11103", "L11104"], "diff": "中", "level": "應用", "stem": "某展覽館需要「高演色性且色溫接近自然日光」的光源，下列哪一個最符合？", "opts": ["Ra 75、6500 K 的 LED", "Ra 95、5500 K 的 LED", "Ra 95、2700 K 的 LED", "Ra 75、5500 K 的 LED"], "explain": "兩個條件要同時滿足：演色性高（Ra ≥ 90），且色溫接近日光（約 5000–6500 K）。", "trap": "", "src": "科目一指引 1.3、1.4", "origin": "學生協助命題（115 審修）", "fam": "lightspec", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "B"}, {"id": "L13-1035", "codes": ["L13104"], "diff": "易", "level": "知識", "stem": "使用分光光度儀量測表面色之前，通常需要進行哪一種校正？", "opts": ["黑歸零校正（光源色量測）", "高光澤黑玻璃校正", "藍板校正", "白板校正"], "explain": "表面色量測以白板校正，取得光譜反射率；光源色量測用黑歸零；光澤計用高光澤黑玻璃。", "trap": "", "src": "科目三指引 2.1（第 2-31、2-37 頁）", "origin": "學生協助命題（115 審修）", "fam": "calib", "type": "mc", "subj": "L13", "dom": "D6", "diag": false, "ans": "D"}, {"id": "L13-1036", "codes": ["L13104"], "diff": "易", "level": "理解", "stem": "要量測白光 LED 這類光譜中有尖峰的光源，取得精細的光譜功率分布，分光元件與取樣間隔應如何選擇？", "opts": ["使用繞射光柵等精細分光元件，取樣間隔至少 5 nm", "使用寬頻濾鏡的色度計即可，取樣間隔不影響結果", "使用 10 nm 以上的取樣間隔即可，與物體色相同", "使用光澤計量測"], "explain": "光源可能有窄頻帶成分，需要較精細的分光（目前多用繞射光柵）並至少以 5 nm 取樣；物體反射率曲線較平滑，10 nm 間隔即可。寬頻濾鏡無法取得精細光譜。", "trap": "把物體色的取樣條件套用到光源。", "src": "科目三指引 2.1（第 2-31 頁）", "origin": "學生協助命題（115 審修）", "fam": "L13-1036", "type": "mc", "subj": "L13", "dom": "D6", "diag": false, "ans": "A"}, {"id": "L13-1037", "codes": ["L13104"], "diff": "易", "level": "理解", "stem": "下列哪一種色彩量測不需要儀器提供照明光源？", "opts": ["表面色量測", "透明色（穿透色）量測", "光源色量測", "反射率量測"], "explain": "光源色量測的對象本身就會發光；表面色與穿透色都要由儀器提供照明再量測反射或透射。", "trap": "", "src": "科目三指引 2.1（第 2-31 頁）", "origin": "學生協助命題（115 審修）", "fam": "L13-1037", "type": "mc", "subj": "L13", "dom": "D6", "diag": false, "ans": "C"}, {"id": "L13-1038", "codes": ["L13303"], "diff": "易", "level": "理解", "stem": "色彩管理系統中的色彩描述檔（ICC profile）主要定義了什麼關係？", "opts": ["色光三原色與色料三原色的混色關係", "裝置色彩空間（如 RGB、CMYK）與 CIE 色度系統之間的對應", "光譜反射率與色溫的對應", "物體材質與光澤的對應"], "explain": "描述檔記錄裝置訊號與裝置無關色度值（XYZ 或 LAB）的對應，是轉換的依據。", "trap": "", "src": "科目一指引 2.6；科目三指引 2.3", "origin": "學生協助命題（115 審修）", "fam": "L13-1038", "type": "mc", "subj": "L13", "dom": "D7", "diag": false, "ans": "B"}, {"id": "L13-1039", "codes": ["L13204"], "diff": "易", "level": "應用", "stem": "相機以「灰色世界法」做自動白平衡。拍攝下列哪一種畫面時，最容易修錯顏色？", "opts": ["畫面大部分是一大片綠色草地", "色彩分布均勻的街景", "有白牆與灰色地面的室內", "包含灰卡的商品照"], "explain": "灰色世界法假設整張影像的平均色是灰色。畫面被單一顏色佔滿時平均不是灰，系統會誤把草地的綠當成偏色而往洋紅方向修正。", "trap": "", "src": "科目三指引 2.3（第 2-44～2-45 頁）", "origin": "學生協助命題（115 審修）", "fam": "wb", "type": "mc", "subj": "L13", "dom": "D7", "diag": false, "ans": "A"}, {"id": "L13-1040", "codes": ["L13205", "L13302", "L13303"], "diff": "難", "level": "分析", "stem": "印刷廠要印製產品型錄，封面與內頁由不同人製作。為了確保整本色彩一致，下列哪一種做法最合適？", "opts": ["封面與內頁各自依經驗獨立調色", "依 ISO 12647-2 校準印刷條件，使用相符的 CMYK 描述檔，封面與內頁都在同一套色彩管理流程中轉換", "直接使用印刷機的預設設定，不需描述檔", "封面改用 RGB 直接輸出，色彩更鮮豔"], "explain": "一致性來自同一套標準：校準到印刷規範、以相符描述檔做特性描述與轉換。", "trap": "", "src": "科目三指引 2.3（第 2-43 頁）；徐明景簡報", "origin": "學生協助命題（115 審修）", "fam": "L13-1040", "type": "mc", "subj": "L13", "dom": "D7", "diag": false, "ans": "B"}, {"id": "L13-1041", "codes": ["L13104"], "diff": "易", "level": "理解", "stem": "某印刷廠量測樣品時使用 d/8°（SPEX）幾何條件，下列敘述何者正確？", "opts": ["8° 方向照明，擴散觀測，含鏡面反射", "擴散照明，8° 方向觀測，含鏡面反射", "8° 方向照明，擴散觀測，不含鏡面反射", "擴散照明，8° 方向觀測，不含鏡面反射"], "explain": "斜線前為照明、後為觀測；d 為擴散（積分球）；SPEX 為 specular excluded。", "trap": "", "src": "科目三指引 2.1（第 2-35 頁）", "origin": "學生協助命題（115 審修）", "fam": "spex", "type": "mc", "subj": "L13", "dom": "D6", "diag": false, "ans": "D"}];
